const test2: Question[] = [
  { id: 1, question: "What is the six figure grid reference of the dip tank in the left top corner of the map?", options: ["359 756", "366 759", "751 364", "759 356"], correctAnswer: 0, tip: "Six-figure grid references give easting first then northing; the dip tank in the top-left lies at 359 756." },
  { id: 2, question: "Find the distance of the main road from the western edge of the map in 3468 to the southern edge in 4063.", options: ["6.5 kilometres", "7.0 kilometres", "7.8 kilometres", "8.7 kilometres"], correctAnswer: 2, tip: "Measuring the curving main road between the two grid squares using a piece of string gives about 7.8 km." },
  { id: 3, question: "What is the general direction of the flow of Mukwadzi River?", options: ["North East to South West", "North West to South East", "South East to North West", "South West to North East"], correctAnswer: 0, tip: "Rivers flow from higher to lower contours; Mukwadzi River descends from the NE highlands toward the SW." },
  { id: 4, question: "What is the bearing of a dip tank near the unmarked spot height 1321 in square 4470 from the dip tank in square 3869?", options: ["10°", "80°", "100°", "260°"], correctAnswer: 1, tip: "Bearings are measured clockwise from north; the target lies almost due east, giving about 080°." },
  { id: 5, question: "What drainage pattern is dominant in Kildonan?", options: ["Dendritic", "Radial", "Rectangular", "Trellised"], correctAnswer: 0, tip: "Tributaries joining the main river at acute angles like branches of a tree show a dendritic pattern." },
  { id: 6, question: "According to map evidence, which feature shows that there is livestock rearing in Kildonan?", options: ["Dams", "Dip tanks", "Paddocks", "Vegetation"], correctAnswer: 1, tip: "Dip tanks treat cattle against ticks, so their presence is direct evidence of livestock rearing." },
  { id: 7, question: "Which one of the following physical features is between the two mountain ranges?", options: ["Col", "Gap", "Gorge", "Plateau"], correctAnswer: 0, tip: "A col is a low saddle or pass between two higher peaks or ranges." },
  { id: 8, question: "Which one of the following is not found in Kildonan?", options: ["Forestry", "Housing", "Mining", "Plantation farming"], correctAnswer: 3, tip: "The map shows woodlots, settlements and mine workings, but no large plantation farms." },
  { id: 9, question: "Which one of the following vegetation is dominant in Kildonan?", options: ["Dense bush", "Medium bush", "Recreation", "Trade"], correctAnswer: 1, tip: "Map symbols show scattered shrubs and small trees — characteristic of medium bush vegetation." },
  { id: 10, question: "According to map evidence, Kildonan can be referred to as a ... centre.", options: ["administrative", "mining", "trading", "tourist"], correctAnswer: 1, tip: "Mine shafts, dumps and related infrastructure dominate, making it primarily a mining centre." },
  { id: 11, question: "What settlement pattern characterises Kildonan?", options: ["Cluster", "Dispersed", "Isolated", "Linear"], correctAnswer: 0, tip: "Houses grouped closely together around the mine form a clustered (nucleated) settlement." },
  { id: 12, question: "What man-made feature is commonly found near the cultivated areas of Kildonan?", options: ["Dams", "Embankments", "Powerlines", "Railway lines"], correctAnswer: 0, tip: "Small dams are built near cultivated land to provide water for irrigation and livestock." },
  { id: 13, question: "A world map shows a dashed line X running roughly along the 180° meridian. Which one is true about line X?", options: ["All lines of longitudes are measured from line X.", "One loses or gains two hours upon crossing line X.", "The beginning and ending of the earth's rotation is marked by line X.", "Upon crossing line X the date changes."], correctAnswer: 3, tip: "Line X is the International Date Line; crossing it changes the calendar date by one day." },
  { id: 14, question: "On which of the following days will places along latitude 23½°N have 12 hours of daylight and 12 hours of darkness?", options: ["22nd December and 21st June", "21st June and 23rd December", "21st March and 21st June", "21st March and 23rd September"], correctAnswer: 3, tip: "Day and night are equal everywhere on Earth at the equinoxes — 21 March and 23 September." },
  { id: 15, question: "What is the angle of elevation of the midday sun for a place on latitude 58°S on 22 December?", options: ["24½°", "54½°", "66½°", "67½°"], correctAnswer: 1, tip: "On 22 Dec the sun is overhead at 23½°S, so elevation = 90° − (58° − 23½°) ≈ 55½° (≈54½°)." },
  { id: 16, question: "A diagram shows an asymmetrical fold in rock layers. What feature is labelled Z (the down-folded part)?", options: ["Syncline", "Overfold", "Nappe", "Anticline"], correctAnswer: 0, tip: "A syncline is the trough or down-folded part of a fold, where rock layers dip toward a central axis." },
  { id: 17, question: "The mechanical grinding of the river's traction load against the banks and bed of the river is called ...", options: ["attrition.", "corrasion.", "corrosion.", "hydraulic action."], correctAnswer: 1, tip: "Corrasion (abrasion) is the scraping/grinding of the bed and banks by the load the river carries." },
  { id: 18, question: "A river profile shows pronounced meanders with a cut-off feature labelled B. What is likely to be formed at B?", options: ["Braided river", "Estuary", "Flood plain", "Ox-bow lake"], correctAnswer: 3, tip: "When a meander neck is cut off, the abandoned loop becomes an ox-bow lake." },
  { id: 19, question: "The drainage pattern that is most likely to be formed from a volcanic cone is ...", options: ["dendritic.", "radial.", "rectangular.", "trellis."], correctAnswer: 1, tip: "Streams flow outward from the summit of a volcanic cone in all directions, producing a radial pattern." },
  { id: 20, question: "The molten rock ejected from underneath the earth's crust to the surface is called ...", options: ["dyke.", "lava.", "magma.", "sill."], correctAnswer: 1, tip: "Magma becomes lava once it reaches and flows on the Earth's surface." },
  { id: 21, question: "A diagram shows alternating bands of hard and softer rock on a slope, with water dropping over the hard band. What name is given to the feature?", options: ["Cataract", "Interlocking spur", "Levee", "Waterfall"], correctAnswer: 3, tip: "Where a river crosses a hard rock band overlying softer rock, differential erosion creates a waterfall." },
  { id: 22, question: "A diagram shows tree roots forcing their way into joints and bedding planes of rock. The type of weathering taking place is ...", options: ["biotic action.", "exfoliation.", "frost action.", "oxidation."], correctAnswer: 0, tip: "Plants and animals breaking rock (e.g. roots prising joints) is biological/biotic weathering." },
  { id: 23, question: "Which one of the climatic regions has the largest daily range of temperature?", options: ["Equatorial", "Hot desert", "Mediterranean", "Savanna"], correctAnswer: 1, tip: "Cloudless skies in hot deserts allow intense daytime heating and rapid night cooling, giving a huge diurnal range." },
  { id: 24, question: "A map of Africa shows a shaded region between latitudes 23½°N and 23½°S. The shaded region experiences ... climate.", options: ["equatorial", "tropical continental", "tropical desert", "tropical marine"], correctAnswer: 1, tip: "Most of inland tropical Africa between the tropics has a tropical continental (savanna) climate." },
  { id: 25, question: "What environmental hazard can be associated with hot deserts?", options: ["Typhoons", "Earthquakes", "Dust", "Blizzards"], correctAnswer: 2, tip: "Dry, loose surface material and strong winds cause dust storms — a hazard typical of hot deserts." },
  { id: 26, question: "Scattered trees and tall grass are commonly found in ...", options: ["desert.", "equatorial.", "Mediterranean.", "savanna."], correctAnswer: 3, tip: "Savanna vegetation is characterised by tall grasses with scattered drought-resistant trees." },
  { id: 27, question: "A climate table for station X shows highest rainfall in October–December and low rainfall in June–August. During which season does station X receive maximum rainfall?", options: ["Autumn", "Spring", "Summer", "Winter"], correctAnswer: 0, tip: "Peak rainfall in Oct–Dec in the southern hemisphere falls in the autumn (Mediterranean-type) season." },
  { id: 28, question: "On a map of Africa showing climatic regions, what is the characteristic feature of the natural vegetation of climatic region R?", options: ["Deciduous", "Evergreen", "Hydrophytic", "Xerophytic"], correctAnswer: 3, tip: "Region R lies in the desert belt, where xerophytic (drought-resistant) plants dominate." },
  { id: 29, question: "State the climatic region in shaded area P on the map of Africa.", options: ["Equatorial", "Hot deserts", "Mediterranean", "Savanna"], correctAnswer: 2, tip: "Area P lies at the northern and southern tips of Africa, which have a Mediterranean climate." },
  { id: 30, question: "Which one of the following vegetation is typical of climatic conditions with winter rains and summer droughts?", options: ["Cacti, thorn bushes and date palms", "Cork oak, cedar and cypress", "Mahogany, ebony and orchids", "Teak, sal and bamboo"], correctAnswer: 1, tip: "Mediterranean climates (winter rain, summer drought) support cork oak, cedar and cypress." },
  { id: 31, question: "Which one of the following plants is adapted to saline conditions?", options: ["Cedar", "Cork oak", "Mahogany", "Mangrove"], correctAnswer: 3, tip: "Mangroves are halophytes that thrive in salty coastal mud." },
  { id: 32, question: "The following are natural hazards except ...", options: ["cyclones.", "deforestation.", "floods.", "tsunamis."], correctAnswer: 1, tip: "Deforestation is a human activity, not a natural hazard." },
  { id: 33, question: "A number of towns which have grown and joined together is referred to as ...", options: ["conurbation.", "cosmopolitan.", "metropolitan.", "satellite."], correctAnswer: 0, tip: "A conurbation is formed when neighbouring towns expand and merge into one continuous urban area." },
  { id: 34, question: "Which one of the following is not a push factor leading to rural-urban migration?", options: ["Lack of employment in rural areas", "Land disputes in rural areas", "Limited social services in rural areas", "Rural electrification"], correctAnswer: 3, tip: "Rural electrification improves rural life and discourages migration — it is a pull/retain factor, not a push." },
  { id: 35, question: "A world map shades areas X (high latitudes) and Y (low latitudes around the tropics). Why are shaded areas X and Y sparsely populated?", options: ["X: Extreme low temperature; Y: Extreme high temperature", "X: Extreme high temperature; Y: Extreme low temperature", "X: Thick forests; Y: Waterlogged soils", "X: Waterlogged soils; Y: Thick forests"], correctAnswer: 0, tip: "Polar region X is too cold to support large populations; desert region Y is too hot and dry." },
  { id: 36, question: "Which of the following best describes what life expectancy is?", options: ["Number of years a person is expected to live.", "Number of years a person is expected to be very productive.", "Period when resources available can sustain the population.", "Period when the fertility rate of the population is at its highest."], correctAnswer: 0, tip: "Life expectancy is the average number of years a person is expected to live from birth." },
  { id: 37, question: "A population pyramid has a narrow base widening in the middle and tapering at the top. Which statement is not correct about the population structure?", options: ["Low birth rate", "Low fertility rate", "High life expectancy", "High fertility rate"], correctAnswer: 3, tip: "A narrow base shows few young children, indicating low (not high) fertility." },
  { id: 38, question: "The maximum number of population an environment can sustain adequately without causing degradation is called ...", options: ["carrying capacity.", "maximum load.", "population density.", "resource degradation."], correctAnswer: 0, tip: "Carrying capacity is the population size an environment can support sustainably." },
  { id: 39, question: "Why are most areas of Asia highly populated? The areas ...", options: ["are highly industrialised.", "have plenty of minerals.", "have fertile alluvial soils.", "have plenty of wild fruits."], correctAnswer: 2, tip: "Fertile alluvial river plains (e.g. Ganges, Yangtze) support intensive agriculture and dense populations." },
  { id: 40, question: "Sweet potatoes, yams, cassava and cocoyam are examples of ...", options: ["cereal crops.", "fibre crops.", "root crops.", "vegetable oils."], correctAnswer: 2, tip: "These edible underground tubers are classed as root (tuber) crops." },
  { id: 41, question: "A world map shades major wheat-growing belts in North America, Eurasia, Argentina and Australia. The shaded areas are ... output.", options: ["mechanised with large wheat", "intensified with large rice", "commercialised with large coffee", "intensified with large sugarcane"], correctAnswer: 0, tip: "These temperate belts are the world's mechanised, large-scale wheat-producing regions." },
  { id: 42, question: "Why is agriculture done on a small scale in Equatorial regions despite receiving a lot of rainfall?", options: ["There are a lot of wild fruits for people to eat.", "There are plenty of wild animals that destroy crops.", "The high temperatures dry up the crops.", "The rains cause waterlogging which is not good for crops."], correctAnswer: 3, tip: "Heavy continuous rainfall waterlogs soils and leaches nutrients, making large-scale farming difficult." },
  { id: 43, question: "When land is allowed to rest in order to regain its nutrients and retain moisture it is called ...", options: ["contour ploughing.", "fallowing.", "strip cropping.", "terracing."], correctAnswer: 1, tip: "Fallowing is leaving land uncultivated for a period to restore fertility and moisture." },
  { id: 44, question: "The best crop to be rotated with other crops due to its nutritional (nitrogen-fixing) value is ...", options: ["beans.", "cotton.", "hay.", "maize."], correctAnswer: 0, tip: "Beans (a legume) fix atmospheric nitrogen into the soil, enriching it for the next crop." },
  { id: 45, question: "The world's greatest rice producer is ...", options: ["India.", "Indonesia.", "South Korea.", "Thailand."], correctAnswer: 0, tip: "India is among the world's largest rice producers (with China); of the options given, India is the greatest." },
  { id: 46, question: "What type of coal is coking coal?", options: ["Anthracite", "Bituminous", "Lignite", "Peat"], correctAnswer: 1, tip: "Bituminous coal is heated in the absence of air to produce coke for the steel industry." },
  { id: 47, question: "A diagram shows a reservoir, head, turbine and generator producing electricity from flowing water. The diagram shows the generation of ... power.", options: ["hydro", "nuclear", "solar", "wind"], correctAnswer: 0, tip: "Falling water spinning a turbine connected to a generator is hydro-electric power generation." },
  { id: 48, question: "The highest producer of natural gas is ...", options: ["China.", "United Kingdom.", "United States of America.", "West Germany."], correctAnswer: 2, tip: "The United States is the world's largest producer of natural gas." },
  { id: 49, question: "What factor largely contributes to the low production of solar energy? Climate conditions and lack of ...", options: ["capital.", "labour.", "modern technology.", "space for building."], correctAnswer: 2, tip: "Solar power needs advanced technology (panels, inverters, storage) which many countries lack." },
  { id: 50, question: "The advantage of thermal power stations over hydro power stations is that they ...", options: ["cannot be affected by drought.", "deplete the ozone layer.", "are cheaper to run and manage.", "lead to global warming."], correctAnswer: 0, tip: "Thermal stations burn fuel to produce steam and so are not dependent on rainfall, unlike hydro stations which can be hit by drought." },
];

geographyTests[1] = test2;

const test3: Question[] = [
  { id: 1, question: "Find the six figure grid reference of the Trigonometrical Station 527/T.", options: ["721 964", "726 194", "734 195", "193 735"], correctAnswer: 2, tip: "Six-figure grid references give easting first then northing; 527/T lies at 734 195." },
  { id: 2, question: "Find the length of the Masuwe River from grid 72 to grid 74 in metres.", options: ["3 000", "3 800", "4 600", "5 000"], correctAnswer: 2, tip: "Measuring the river's curving course between the two grid lines using a string gives about 4 600 m." },
  { id: 3, question: "What is the bearing of the unmarked spot height 927 from the view point?", options: ["75°", "105°", "160°", "220°"], correctAnswer: 2, tip: "Bearings are measured clockwise from north; the spot lies south and slightly east, giving about 160°." },
  { id: 4, question: "What tourist attraction is found in grid square 7718?", options: ["An embankment", "National monument", "Pump house", "Railway line cross"], correctAnswer: 1, tip: "The map symbol in grid square 7718 marks a national monument — a tourist attraction." },
  { id: 5, question: "Which one of the following modes of transport are tourists not likely to use when getting into Victoria Falls Town?", options: ["Air transport", "Railway transport", "Road transport", "Water transport"], correctAnswer: 3, tip: "The Zambezi gorge below the Falls is not navigable, so tourists do not arrive by water." },
  { id: 6, question: "From map evidence, which one of the following economic activities is not carried out in Victoria Falls?", options: ["Farming", "Power transmission", "Railway transport", "Tourism"], correctAnswer: 0, tip: "The map shows powerlines, railway and tourist sites but no cultivated/farming areas." },
  { id: 7, question: "What is the direction of Princes Elizabeth Island in grid square 7720 from Canary Island in square 7422?", options: ["North East", "North West", "South East", "South West"], correctAnswer: 2, tip: "Square 7720 lies to the south and east of 7422, giving a south-east direction." },
  { id: 8, question: "What is the difference in the height of land between Musuwe Falls in grid square 7813 and Game Park entrance gate in grid square 7313?", options: ["10m", "20m", "30m", "40m"], correctAnswer: 1, tip: "Reading the contour values at the two points gives a height difference of about 20 m." },
  { id: 9, question: "What type of vegetation is dominant on the map extract of Victoria Falls Town?", options: ["Medium bush", "Sparse bush", "Very dense bush", "Very open bush"], correctAnswer: 0, tip: "The vegetation symbols across the extract represent medium bush cover." },
  { id: 10, question: "The channel of the Zambezi River East of grid line 78 and South of grid line 16 can be described as ...", options: ["flat.", "narrow.", "steep.", "wide."], correctAnswer: 1, tip: "Below the Falls the river flows in a deep, narrow gorge — closely spaced contours either side." },
  { id: 11, question: "In which of the following grid squares is there evidence for generation of electricity?", options: ["7620", "7718", "7812", "7917"], correctAnswer: 2, tip: "Square 7812 contains the Victoria Falls hydro-power station symbol." },
  { id: 12, question: "A cross-section diagram is drawn along grid line 20. Which one of the following diagrams represents a correct cross section of the map along grid line 20?", options: ["A", "B", "C", "D"], correctAnswer: 1, tip: "Option B matches the contour heights crossed along grid line 20 — gentle rise then a slight dip." },
  { id: 13, question: "The 0° line of longitude that passes through Greenwich is called the ...", options: ["Equator.", "International Date Line.", "Prime Meridian.", "Tropic of Cancer."], correctAnswer: 2, tip: "The Greenwich (0°) meridian is known as the Prime Meridian." },
  { id: 14, question: "The earth rotates on its axis through 360° in 24 hours, giving a rate of ...", options: ["1° per hour.", "4° per hour.", "15° per hour.", "60° per hour."], correctAnswer: 2, tip: "360° ÷ 24 h = 15° of longitude per hour." },
  { id: 15, question: "If the local time in Georgetown (Guyana) 60°W is 01:35 hours, what will be the local time in Bangkok (Thailand) 100°E?", options: ["02:40 hours", "04:15 hours", "10:40 hours", "12:15 hours"], correctAnswer: 3, tip: "Difference = 160° at 4 min per degree = 640 min = 10h 40min ahead. 01:35 + 10:40 = 12:15." },
  { id: 16, question: "A diagram shows down-cutting by rivers and glaciers into an originally flat plateau surface, leaving isolated peaks. The diagram illustrates the formation of ...", options: ["fold mountains.", "intermont plateau.", "residual mountains.", "volcanic plateau."], correctAnswer: 2, tip: "When erosion removes most of a plateau, isolated remnants left standing are residual mountains." },
  { id: 17, question: "Which of the following lists contain a river's load carried as traction?", options: ["Boulders, pebbles and stones", "Dissolved matter in water", "Silt, mud and dead wood", "Silt, stones and boulders"], correctAnswer: 0, tip: "Traction is the rolling/dragging of large material (boulders, pebbles, stones) along the bed." },
  { id: 18, question: "Which of the following factors is responsible for all forms of mass movement?", options: ["Gravity", "Moisture", "Pressure", "Temperature"], correctAnswer: 0, tip: "All mass movements (slides, flows, falls) occur because gravity pulls material downslope." },
  { id: 19, question: "A river cross-section shows two sea-level lines, with terraces cut above the current channel. What does the diagram illustrate?", options: ["Formation of rapids", "River flooding", "River rejuvenation", "River terracing"], correctAnswer: 2, tip: "A drop in base level causes a river to cut a new channel within its old valley — rejuvenation." },
  { id: 20, question: "A geological block diagram shows a vertical igneous intrusion (A) cutting across rock layers and standing up as a ridge. Which of the following is true about part A?", options: ["Sill resistant to denudation.", "Sill not resistant to denudation.", "Dyke resistant to denudation.", "Dyke not resistant to denudation."], correctAnswer: 2, tip: "A vertical intrusion is a dyke; standing as a ridge means it resists erosion better than the surrounding rock." },
  { id: 21, question: "Which one of the following is not a process of chemical weathering?", options: ["Decomposition", "Frost action", "Oxidation", "Solution"], correctAnswer: 1, tip: "Frost action (freeze–thaw) is physical/mechanical weathering, not chemical." },
  { id: 22, question: "A diagram shows a large basin-shaped depression at the summit of a volcano formed after the cone collapsed. The volcanic feature X is called ...", options: ["caldera.", "crater.", "dyke.", "spine."], correctAnswer: 0, tip: "A very large depression formed by collapse of a magma chamber is a caldera." },
  { id: 23, question: "The Tropical Continental (Savanna) type of climate is best described as having ...", options: ["hot, wet autumn and cool dry spring.", "much rain all year round.", "summer rain and winter drought.", "winter rain and summer drought."], correctAnswer: 2, tip: "Savanna climate has a distinct wet summer and a dry winter." },
  { id: 24, question: "A weather system has high pressure in the centre, isobars far apart and winds moving anticlockwise. The description refers to ...", options: ["a cyclone in the Northern hemisphere.", "a cyclone in the Southern hemisphere.", "an anticyclone in the Northern hemisphere.", "an anticyclone in the Southern hemisphere."], correctAnswer: 3, tip: "High pressure = anticyclone; anticlockwise circulation around a high occurs in the Southern hemisphere." },
  { id: 25, question: "Regarding the greenhouse effect, what role do the greenhouse gases play?", options: ["Allow more heat from the sun to enter the atmosphere.", "Generate additional heat through chemical reactions.", "Help humid air to hold more heat within the atmosphere.", "Trap heat that is reflected from the surface of the earth."], correctAnswer: 3, tip: "Greenhouse gases absorb and re-radiate long-wave heat re-emitted by Earth's surface, warming the lower atmosphere." },
  { id: 26, question: "Why do the hot deserts experience cold nights? Due to ...", options: ["cloud cover.", "clear skies.", "low air pressure.", "high solar insolation."], correctAnswer: 1, tip: "Clear desert skies allow rapid loss of long-wave radiation at night, so temperatures fall sharply." },
  { id: 27, question: "A climatic graph for town X shows uniformly high temperatures (~26°C) and heavy rainfall in every month. What type of climate is experienced by town X?", options: ["Hot desert", "Hot wet equatorial", "Mediterranean", "Savanna"], correctAnswer: 1, tip: "Constant high temperature and rainfall throughout the year is the hot wet equatorial climate." },
  { id: 28, question: "A map of Africa shows area X on the equator (East African highlands). Which of the following is a reason why area X does not experience equatorial climatic conditions despite being on the equator?", options: ["Coastal location has modified temperatures.", "Its lower altitude discourages formation of rainy clouds.", "The higher altitude has resulted into lower temperatures.", "The North East monsoon winds do not reach the area."], correctAnswer: 2, tip: "The high altitude of the East African plateau lowers temperatures, giving a modified (cooler) climate." },
  { id: 29, question: "Which one of the following towns has the Savanna type of climate?", options: ["Algiers", "Cairo", "Cape Town", "Khartoum"], correctAnswer: 3, tip: "Khartoum lies in the tropical savanna belt with hot wet summers and dry winters." },
  { id: 30, question: "Plants have few or no leaves and their foliage is either waxy, leathery or needle shaped. This describes the ... vegetation.", options: ["Equatorial", "Hot desert", "Mediterranean", "Savanna"], correctAnswer: 1, tip: "These xerophytic adaptations reduce water loss in hot desert vegetation." },
  { id: 31, question: "Which one of the following climatic regions has the smallest daily range of temperature?", options: ["Equatorial", "Hot desert", "Mediterranean", "Savanna"], correctAnswer: 0, tip: "Constant cloud cover and high humidity in equatorial regions keep day and night temperatures very close." },
  { id: 32, question: "The Savanna vegetation has adapted to the climate by the following ways except ...", options: ["having broad leaves.", "having broad trunks.", "having long tap roots.", "shedding of leaves."], correctAnswer: 0, tip: "Savanna trees have small, often hairy leaves to limit water loss — broad leaves are not an adaptation." },
  { id: 33, question: "Which one of the following African countries has the highest population?", options: ["Democratic Republic of Congo", "Egypt", "Ethiopia", "South Africa"], correctAnswer: 2, tip: "Of the four, Ethiopia has the largest population (well over 100 million)." },
  { id: 34, question: "The average number of children that would be born to each woman during her reproductive period is known as ...", options: ["birth rate.", "fertility rate.", "life expectancy.", "mortality."], correctAnswer: 1, tip: "Total fertility rate measures the average number of children per woman over her reproductive years." },
  { id: 35, question: "A world map shades densely populated areas of Western Europe and the eastern USA. Two factors which have attracted more people in the shaded areas are ...", options: ["industries and fertile land.", "lack of natural disasters and cooler climate.", "warmer climate and fertile soils.", "wetter conditions and industries."], correctAnswer: 0, tip: "These regions combine fertile farmland with concentrated industries — both major pull factors." },
  { id: 36, question: "The growth of population creates an urgent need for ...", options: ["commercial activities.", "extensive agriculture.", "housing.", "industrialisation."], correctAnswer: 2, tip: "Rapid population growth increases demand for shelter most urgently." },
  { id: 37, question: "What does the term 'Zero Growth' mean in population studies?", options: ["No more babies are being born.", "There are more baby boys born than girls.", "There are more baby girls born than boys.", "The population remains constant."], correctAnswer: 3, tip: "Zero population growth means births equal deaths, so total population stays constant." },
  { id: 38, question: "Why is there a lower birth rate in industrial areas than in agricultural areas?", options: ["Industrial workers are more aware of family planning.", "Married couples are usually separated in industrial areas.", "Pollution in industrial areas reduces the fertility of women.", "There are fewer women in industrial areas."], correctAnswer: 0, tip: "Better education and access to family planning in industrial areas lowers the birth rate." },
  { id: 39, question: "Which one of the following lists of crops may not be produced under market gardening?", options: ["Cabbage, green maize, cucumber", "Carrots, tomatoes, green beans", "Carrots, silk, oranges", "Cucumber, onions, lettuce"], correctAnswer: 2, tip: "Silk is produced from silkworms, not market gardens — and oranges are usually orchard, not market-garden, crops." },
  { id: 40, question: "In an area of extensive livestock farming, under what conditions are cattle likely to be replaced by sheep? When ...", options: ["markets become closer.", "transport becomes better.", "land becomes less drained.", "pasture becomes sparse."], correctAnswer: 3, tip: "Sheep can graze on poorer, sparser pasture than cattle, so they replace cattle in such areas." },
  { id: 41, question: "Which of the following is the least applicable to plantation agriculture in the world?", options: ["Average yields from plantations are higher.", "Crops raised in plantations are mainly for export.", "Plantations are much larger in acreage.", "The plantations are entirely owned by foreigners."], correctAnswer: 3, tip: "Many plantations are now owned by local companies or governments, so 'entirely owned by foreigners' is least true." },
  { id: 42, question: "A map of Africa shades an area in the south. Which one of the following crops is mainly produced in the shaded area?", options: ["Maize", "Rice", "Sugarcane", "Wheat"], correctAnswer: 0, tip: "Southern Africa (especially South Africa, Zimbabwe and Zambia) is a major maize-producing region." },
  { id: 43, question: "A bar graph of the five major coffee producers shows W as the tallest bar (about 60+). Which country is represented by the letter W?", options: ["Brazil", "Ethiopia", "Guatemala", "Mexico"], correctAnswer: 0, tip: "Brazil is by far the world's largest coffee producer." },
  { id: 44, question: "Which of the following is a type of extensive farming?", options: ["Dairy farming", "Fish farming", "Ranching", "Truck farming"], correctAnswer: 2, tip: "Ranching uses very large areas of land with low inputs per hectare — extensive farming." },
  { id: 45, question: "Which of the following crops might lead to deforestation during its processing stage?", options: ["Cotton", "Maize", "Sugar cane", "Tobacco"], correctAnswer: 3, tip: "Tobacco curing requires large amounts of firewood, leading to extensive deforestation." },
  { id: 46, question: "Which of the following sources of power is renewable?", options: ["Coal", "Gas", "Oil", "Water"], correctAnswer: 3, tip: "Water (hydro) is naturally replenished by the water cycle — a renewable source." },
  { id: 47, question: "Oil tankers today are increasing in size because ...", options: ["transportation costs per unit oil are low.", "there is no risk of fire.", "they can carry other cargo.", "they sail the deep seas."], correctAnswer: 0, tip: "Larger tankers achieve economies of scale, lowering the cost of transporting each unit of oil." },
  { id: 48, question: "The electricity generated from hot water or steam from rocks in the earth's crust is referred to as ...", options: ["geothermal.", "hydro-electricity.", "solar.", "thermal."], correctAnswer: 0, tip: "Heat from inside the Earth used to generate electricity is called geothermal power." },
  { id: 49, question: "At a newly discovered oil well, oil is usually brought to the surface by ...", options: ["drilling.", "pipeline.", "pressure.", "pumping."], correctAnswer: 2, tip: "Initially the natural underground pressure forces the oil up to the surface." },
  { id: 50, question: "The leading coal producing country in Africa is ...", options: ["Nigeria.", "South Africa.", "Zambia.", "Zimbabwe."], correctAnswer: 1, tip: "South Africa is by far Africa's largest coal producer." },
];

geographyTests[2] = test3;

const test4: Question[] = [
  { id: 1, question: "Find the six figure grid reference for a water reservoir north east of Zvishavane.", options: ["514 959", "518 964", "959 514", "964 518"], correctAnswer: 1, tip: "Six-figure references give easting first then northing; the NE reservoir lies at 518 964." },
  { id: 2, question: "Find the distance of Shavi River from grid square 970442 to 010422.", options: ["3.9 km", "4.4 km", "5.9 km", "6.9 km"], correctAnswer: 2, tip: "Measuring the river's curving course between the two points using a string gives about 5.9 km." },
  { id: 3, question: "The height of the trigonometrical station in grid square 0043 is ...", options: ["1 030.0 m.", "1 076.6 m.", "1 173.0 m.", "1 179.6 m."], correctAnswer: 3, tip: "The trig station value printed beside the symbol in square 0043 is 1 179.6 m." },
  { id: 4, question: "What is the bearing of the dip tank in grid square 9645 from the trigonometric station in grid square 9042?", options: ["24°", "66°", "114°", "246°"], correctAnswer: 0, tip: "The dip tank lies almost due north and slightly east, giving a bearing of about 024°." },
  { id: 5, question: "What is the major economic activity for the town of Zvishavane?", options: ["Farming", "Fishing", "Mining", "Tourism"], correctAnswer: 2, tip: "Numerous mine shafts, dumps and related infrastructure show that mining is the dominant activity." },
  { id: 6, question: "What evidence is found on the map to show that pastoralism is practised? The presence of ...", options: ["dams.", "dip tanks.", "rivers.", "vegetation."], correctAnswer: 1, tip: "Dip tanks are used to treat livestock against ticks, evidence of pastoralism." },
  { id: 7, question: "According to map evidence, the dominant vegetation in Zvishavane is ...", options: ["dense bush.", "medium bush.", "plantation.", "sparse bush."], correctAnswer: 1, tip: "The vegetation symbols across the extract represent medium bush cover." },
  { id: 8, question: "The dominant settlement pattern in the town of Zvishavane is ...", options: ["cluster.", "dispersed.", "linear.", "random."], correctAnswer: 0, tip: "Buildings are grouped closely together around the mine, forming a clustered (nucleated) settlement." },
  { id: 9, question: "According to the map evidence, which one of the following social services is not provided in Zvishavane town?", options: ["Education", "Health", "Recreation", "Trade"], correctAnswer: 2, tip: "Schools, a hospital and shops are shown but no recreation grounds or sports facilities." },
  { id: 10, question: "A map extract shows closely-spaced contour lines forming hills. The general relief of the map extract is ...", options: ["flat land.", "hilly land.", "low land.", "swampy land."], correctAnswer: 1, tip: "Closely-spaced contours indicate steep slopes and hilly terrain." },
  { id: 11, question: "The drainage pattern of the Shavi River and its tributaries is ...", options: ["braided.", "radial.", "rectangular.", "trellised."], correctAnswer: 2, tip: "The river and its tributaries meet largely at right angles, characteristic of a rectangular pattern." },
  { id: 12, question: "Which one of the following diagrams shows the cross section of the land between a dip tank in grid 9642 and the mine dump in grid 9944?", options: ["A", "B", "C", "D"], correctAnswer: 1, tip: "Option B matches the contour profile — high at both ends with a deep dip in the middle." },
  { id: 13, question: "Which one of the following planets is the hottest and similar in size to planet Earth?", options: ["Mars", "Neptune", "Saturn", "Venus"], correctAnswer: 3, tip: "Venus is similar in size to Earth and is the hottest planet because of its dense CO₂ atmosphere." },
  { id: 14, question: "The sun is directly overhead on the Equator each year on ...", options: ["21 June and 22 December.", "21 March and 21 June.", "21 March and 23 September.", "23 September and 22 December."], correctAnswer: 2, tip: "At the equinoxes (21 March and 23 September) the sun is overhead at the equator." },
  { id: 15, question: "What would be the local time on a ship at longitude 75°W when it is 11:00 hours in London (0°)?", options: ["05:00 hours", "06:00 hours", "15:00 hours", "16:00 hours"], correctAnswer: 1, tip: "75° west of London = 75 × 4 min = 300 min = 5 h behind, so 11:00 − 5:00 = 06:00." },
  { id: 16, question: "Internal Earth's movements operating along horizontal planes moving away from each other are known as ...", options: ["compression forces.", "external forces.", "tension forces.", "vertical movements."], correctAnswer: 2, tip: "Forces pulling rocks apart horizontally are tensional forces." },
  { id: 17, question: "A diagram shows two normal faults with a central block dropped down between them. The feature marked E is a ...", options: ["fault.", "fold.", "graben.", "horst."], correctAnswer: 2, tip: "A central block lowered between two faults is a graben (rift valley)." },
  { id: 18, question: "Chemical weathering is more common ...", options: ["in arid areas.", "in humid tropical regions.", "within the Arctic Circle.", "where winds are dust laden."], correctAnswer: 1, tip: "Heat and abundant moisture in the humid tropics speed up chemical weathering reactions." },
  { id: 19, question: "The overriding portion of the thrust fold is called ...", options: ["graben.", "horst.", "nappe.", "syncline."], correctAnswer: 2, tip: "The over-thrust portion of an over-fold/thrust fault is called a nappe." },
  { id: 20, question: "A river capture diagram shows the sharp bend at X and a dry valley at Y. Which features are represented by letters X and Y?", options: ["X: Elbow of capture, Y: Wind gap", "X: Misfit, Y: Elbow of capture", "X: Pirated stream, Y: Wind gap", "X: Wind gap, Y: Misfit"], correctAnswer: 0, tip: "The sharp bend where capture occurs is the elbow of capture; the abandoned dry valley left behind is the wind gap." },
  { id: 21, question: "Which of the following is a result of tensional movements?", options: ["Dyke", "Horst", "Sill", "Spur"], correctAnswer: 1, tip: "Tension faulting produces horsts (uplifted blocks) and grabens; dykes/sills are igneous intrusions." },
  { id: 22, question: "Mountains of accumulation are also called ...", options: ["block mountains.", "mountains of elevation.", "residual mountains.", "volcanic mountains."], correctAnswer: 3, tip: "Mountains built up by accumulated lava and ash from eruptions are volcanic mountains." },
  { id: 23, question: "A river cross-section shows levees, alluvium and a wide river on bedrock. At which stage of the river is this feature found?", options: ["Delta", "Mountain course", "Plain course", "Valley course"], correctAnswer: 2, tip: "Levees and broad alluvial deposits form on the wide flood plain of a river's plain (lower) course." },
  { id: 24, question: "A climate table shows hot summers (Oct–Mar 23–29°C), cool winters (June 10°C) and rainfall peaking in winter (Jun–Aug 13–16 mm). What type of climate is represented?", options: ["Equatorial", "Mediterranean", "Savanna", "Tropical monsoon"], correctAnswer: 1, tip: "Hot dry summers and rain concentrated in the cool winter months is the Mediterranean pattern." },
  { id: 25, question: "Which one of the following towns experiences the type of climate referred to in the previous question?", options: ["Cape Town", "Gaborone", "Khartoum", "Kinshasa"], correctAnswer: 0, tip: "Cape Town has a Mediterranean climate with winter rainfall and dry summers." },
  { id: 26, question: "The Horse latitudes are located between ...", options: ["30°N and 30°S.", "40°N and 40°S.", "50°N and 50°S.", "60°N and 60°S."], correctAnswer: 0, tip: "The Horse latitudes are the high-pressure belts located around 30° north and south." },
  { id: 27, question: "In which of the following climatic regions are typhoons likely to occur?", options: ["Antarctic region", "Arctic region", "High pressure region", "Low pressure region"], correctAnswer: 3, tip: "Typhoons (tropical cyclones) form over warm tropical oceans where pressure is low." },
  { id: 28, question: "Why are the windward slopes of coastal mountains wetter than the leeward slopes? This is because ...", options: ["descending winds are warm.", "the sea is warmer than the land.", "the winds have to rise to cross them.", "they are nearer the sea."], correctAnswer: 2, tip: "Moist sea winds rise up the windward slope, cool, condense and produce orographic rain." },
  { id: 29, question: "Which of the following factors does not determine the amount of heat received in any part of the earth's surface?", options: ["Distance from the sea", "Latitude", "Longitude", "Relief"], correctAnswer: 2, tip: "Longitude only affects local time, not the amount of solar heat received." },
  { id: 30, question: "What happens when prevailing winds blow parallel to the coast?", options: ["Floods are usually experienced.", "Heavy rainfall is received.", "Little or no rainfall is received.", "Snowfall is experienced."], correctAnswer: 2, tip: "Winds blowing parallel to the coast do not rise inland, so very little rain falls." },
  { id: 31, question: "A world map highlights area Y in the Mediterranean basin (around 30–40°N latitudes). The area marked Y experiences ... climate.", options: ["Hot desert", "Mediterranean", "Savanna", "Tropical Monsoon"], correctAnswer: 1, tip: "Lands around the Mediterranean Sea have a Mediterranean climate." },
  { id: 32, question: "Which of the following plant species are found in area Y (Mediterranean)?", options: ["Baobab and Acacias", "Cacti and Thorn bushes", "Lichens and Mosses", "Pine and Cedar"], correctAnswer: 3, tip: "Drought-resistant evergreens such as pine and cedar dominate Mediterranean vegetation." },
  { id: 33, question: "The area along the Nile Valley is densely populated because of ...", options: ["presence of ancient sites for tourism.", "good transport network.", "fertile soils.", "adequate rainfall."], correctAnswer: 2, tip: "Annual Nile silt deposits create rich fertile soils able to support a dense farming population." },
  { id: 34, question: "Which of the following is the best way of controlling the population?", options: ["Eliminating unwanted pregnancies", "Enhancing family planning", "Improving health care", "Increasing food production"], correctAnswer: 1, tip: "Family planning gives couples direct control over the number and spacing of children." },
  { id: 35, question: "A situation where the available resources match the population of an area is called ...", options: ["maximum population.", "optimum population.", "over population.", "under population."], correctAnswer: 1, tip: "Optimum population is reached when population size and resources give the highest standard of living." },
  { id: 36, question: "The rate of natural increase of population is best defined as the crude ...", options: ["birth rate minus the crude death rate.", "birth rate minus the fertility rate.", "death rate divided by the crude death rate.", "death rate divided by the fertility rate."], correctAnswer: 0, tip: "Natural increase = crude birth rate − crude death rate." },
  { id: 37, question: "A graph of projected world population shows about 12.5 billion in 2075. The projected world population in 2075 is ...", options: ["11.8.", "12.5.", "12.9.", "13.1."], correctAnswer: 1, tip: "Reading the world line at 2075 gives about 12.5 billion." },
  { id: 38, question: "In which of the following continents is rural over-population common?", options: ["Africa", "Asia", "Europe", "North America"], correctAnswer: 1, tip: "Densely-farmed Asian countries (India, Bangladesh, China) suffer rural over-population." },
  { id: 39, question: "A world map shades sparsely populated areas A (Sahara, Africa) and B (interior Australia). Which is the main reason why areas marked A and B are sparsely populated? They are ...", options: ["covered with ice.", "dry and infertile.", "government protected areas.", "mountainous."], correctAnswer: 1, tip: "Both regions are hot deserts with very little rainfall and poor, infertile soils." },
  { id: 40, question: "A population pyramid has a wide base that narrows steeply upward. The pyramid represents ...", options: ["a growing population.", "a medium population.", "an old population.", "a young population."], correctAnswer: 3, tip: "A wide base with rapid narrowing shows many children and few elderly — a young population." },
  { id: 41, question: "The largest producer of tea is ...", options: ["China.", "India.", "Japan.", "Sri Lanka."], correctAnswer: 0, tip: "China is currently the world's largest producer of tea." },
  { id: 42, question: "The following are economic factors influencing agriculture except ...", options: ["labour.", "market.", "soil.", "transport."], correctAnswer: 2, tip: "Soil is a physical (natural) factor, not an economic factor." },
  { id: 43, question: "A bar graph of four major wheat-producing countries lists D with the smallest output (about 2 million tonnes). Which country is represented by the letter D?", options: ["Argentina", "China", "Italy", "United States of America"], correctAnswer: 0, tip: "Of the four, Argentina has the smallest wheat output." },
  { id: 44, question: "The following crops are legumes except ...", options: ["beans.", "groundnuts.", "sunhemp.", "wheat."], correctAnswer: 3, tip: "Wheat is a cereal (grass) — not a legume." },
  { id: 45, question: "Which one of the following crops is not a raw material?", options: ["Coffee", "Oil Palm", "Rubber", "Timber"], correctAnswer: 0, tip: "Coffee is consumed directly as a beverage; the others are processed into industrial raw materials." },
  { id: 46, question: "A map of Africa shades the Mediterranean coast (north Africa). Name the major crop grown in the shaded areas.", options: ["Barley", "Dates", "Oats", "Vines"], correctAnswer: 3, tip: "The Mediterranean coastlands of North Africa are major producers of grapes (vines)." },
  { id: 47, question: "A pie chart of energy consumption shows fuel wood as the largest slice, with small portions for thermal, natural gas, coal and hydro. Which one of the continents is represented in the pie chart?", options: ["Africa", "Asia", "North America", "South America"], correctAnswer: 0, tip: "Heavy reliance on fuel wood is characteristic of Africa's energy mix." },
  { id: 48, question: "The term 'mineral oil' refers to ...", options: ["coal.", "diesel.", "petroleum.", "natural gas."], correctAnswer: 2, tip: "Mineral oil is another name for petroleum (crude oil)." },
  { id: 49, question: "Which of the following statements is true about renewable energy?", options: ["Burning of fuel wood, natural gas and coal", "Combustion of nuclear energy", "The use of hydro-electricity, solar energy and bio-gas", "The use of coal and oil"], correctAnswer: 2, tip: "Hydro, solar and bio-gas are all naturally replenished — renewable energy sources." },
  { id: 50, question: "Which one of the following countries accounts for the least of the world's total production of coal?", options: ["Brazil", "Canada", "China", "Japan"], correctAnswer: 0, tip: "Brazil produces the smallest amount of coal of the four listed countries." },
];

geographyTests[3] = test4;

const test5: Question[] = [
  { id: 1, question: "What man-made feature is found in grid reference 375695?", options: ["Dip tank", "Mine dump", "Factory", "Road"], correctAnswer: 0, tip: "The map symbol at 375 695 marks a dip tank used for treating cattle." },
  { id: 2, question: "The general height above the sea level of the land in grid square 3570 is ...", options: ["1,300m.", "1,280m.", "1,260m.", "1,240m."], correctAnswer: 1, tip: "Reading the contour values that cross square 3570 gives a general height of about 1,280 m." },
  { id: 3, question: "The vertical interval used on the map for Kildonan is ...", options: ["80m.", "60m.", "40m.", "20m."], correctAnswer: 3, tip: "The contour lines on the Kildonan extract are drawn at 20 m vertical intervals." },
  { id: 4, question: "Find the distance along the railway line from the southern edge of the map up to the bridge in grid square 4265.", options: ["3.4 km", "3.0 km", "2.4 km", "2.0 km"], correctAnswer: 1, tip: "Measuring the railway with a string and applying the 1:50 000 scale gives about 3.0 km." },
  { id: 5, question: "What type of landform is found on the north eastern part of the map?", options: ["A Beach", "A Dyke", "A Mountain range", "An Embankment"], correctAnswer: 2, tip: "Closely-spaced contours forming connected high ground in the NE depict a mountain range." },
  { id: 6, question: "The general flow of the Murembwe River is from ...", options: ["north to south.", "south-east to north west.", "south to north.", "south-west to north west."], correctAnswer: 2, tip: "The river drops from higher contours in the south to lower contours in the north." },
  { id: 7, question: "Calculate the gradient along the slope from the summit of Muneni Hill in grid square 4264 to the huts in grid square 3964.", options: ["1 : 14", "1 : 19", "1 : 24", "1 : 29"], correctAnswer: 2, tip: "Gradient = vertical drop ÷ horizontal distance; the calculation gives approximately 1:24." },
  { id: 8, question: "According to map evidence, the main economic activity on the western side of the railway line is ...", options: ["agriculture.", "cattle ranching.", "lumbering.", "mining."], correctAnswer: 3, tip: "Numerous mine shafts and dumps west of the railway show that mining is the main activity." },
  { id: 9, question: "The main type of vegetation that grows on the eastern side of the narrow tarred road on the map is ...", options: ["dense bush.", "medium bush.", "sparse bush.", "plantation."], correctAnswer: 1, tip: "The vegetation symbols east of the narrow tarred road indicate medium bush cover." },
  { id: 10, question: "What physical feature is found along Mukwadzi River at grid reference 439720?", options: ["Confluence", "Delta", "Ox-bow lake", "Rapids"], correctAnswer: 0, tip: "Two streams meeting at 439 720 form a confluence." },
  { id: 11, question: "In which of the following grid squares is orchard farming practised?", options: ["3772", "3872", "3972", "4072"], correctAnswer: 1, tip: "The orchard symbol (rows of dots representing trees) appears in square 3872." },
  { id: 12, question: "Grid square 4475 has the highest concentration of an urban settlement due to the presence of ...", options: ["agriculture activities.", "lumbering.", "railway transport.", "valley."], correctAnswer: 2, tip: "The railway and station in square 4475 attracted growth of the urban settlement." },
  { id: 13, question: "A globe diagram shows points A and B on different latitudes. What is the difference in latitude between points A and B?", options: ["15°", "30°", "45°", "60°"], correctAnswer: 1, tip: "Counting the latitude lines between A and B gives a difference of 30°." },
  { id: 14, question: "Find the latitude for town Y in the Northern Hemisphere whose angle of elevation of the midday sun is 46° on 21st March.", options: ["0°", "25°", "44°", "67°"], correctAnswer: 2, tip: "On the equinox, latitude = 90° − angle of elevation = 90° − 46° = 44°N." },
  { id: 15, question: "Which one of the following planets takes the longest period of time to make one revolution?", options: ["Earth", "Jupiter", "Mars", "Venus"], correctAnswer: 1, tip: "Of these, Jupiter (about 12 Earth years) takes the longest to orbit the Sun." },
  { id: 16, question: "Which of the following is not an aspect of volcanicity?", options: ["Batholith", "Dyke", "Fold", "Geyser"], correctAnswer: 2, tip: "Folds are produced by tectonic compression, not by volcanic (igneous) activity." },
  { id: 17, question: "The soils along the river banks in its lower course are fertile mainly because of the ...", options: ["decomposition of leaves from trees along the banks.", "deposition of silt during the flooding of the plain.", "droppings of animals that come to drink water.", "fishing activities that are done in the lower course."], correctAnswer: 1, tip: "Floods deposit fine, nutrient-rich silt on the plain, building up fertile soils." },
  { id: 18, question: "The drainage pattern likely to be formed on volcanic mountains is ...", options: ["confluence.", "dendritic.", "radial.", "trellis."], correctAnswer: 2, tip: "Streams radiate outward from the central cone, producing a radial pattern." },
  { id: 19, question: "Which of the following materials from an eruption of a volcano makes the movement of people in the nearby places difficult?", options: ["Ash", "Composite cone", "Lava", "Parasitic cone"], correctAnswer: 0, tip: "Thick volcanic ash settles widely and clogs roads, vehicles and air travel, hindering movement." },
  { id: 20, question: "Which one of the following river loads is largely responsible for both lateral and vertical corrasion?", options: ["Material in solution", "Materials in suspension", "Soil creep", "Traction load"], correctAnswer: 3, tip: "The traction load (boulders, pebbles) drags along the bed and banks, causing both vertical and lateral corrasion." },
  { id: 21, question: "The following are river sources except, ...", options: ["lake.", "marsh.", "ocean.", "spring."], correctAnswer: 2, tip: "Rivers flow into the ocean — the ocean is a river's mouth, not its source." },
  { id: 22, question: "The major cause of synclines and anticlines is ... force.", options: ["compression", "rotation", "tension", "vertical"], correctAnswer: 0, tip: "Synclines (troughs) and anticlines (arches) form when rocks are squeezed by compressional forces." },
  { id: 23, question: "Dissected plateaux are caused by ... erosion.", options: ["gully", "lateral", "sheet", "vertical"], correctAnswer: 3, tip: "Vertical (down-cutting) erosion by rivers cuts deep valleys that dissect a plateau." },
  { id: 24, question: "At the delta, a river discharges its water through several channels called ...", options: ["distributaries.", "meanders.", "streams.", "tributaries."], correctAnswer: 0, tip: "The branching channels that fan out across a delta are distributaries." },
  { id: 25, question: "A diagram shows winds blowing from the cool land toward the warmer sea at night. The diagram shows ...", options: ["a cyclone.", "a land breeze.", "a sea breeze.", "an anticyclone."], correctAnswer: 1, tip: "At night the land cools faster than the sea, so wind blows from land to sea — a land breeze." },
  { id: 26, question: "A tropical storm which develops in low pressure systems travelling about 800 km per hour and is very destructive is called ...", options: ["anticyclone.", "hurricane.", "tornado.", "typhoon."], correctAnswer: 2, tip: "Tornadoes are violent rotating storms with extremely high wind speeds." },
  { id: 27, question: "A climate table for Station A shows monthly rainfall of 38, 15, 15, 20, 0, 0, 0, 0, 0, 8, 18 and 36 mm. What is the mean annual rainfall for Station A?", options: ["15 mm", "25 mm", "12.5 mm", "13.5 mm"], correctAnswer: 2, tip: "Total rainfall = 150 mm; mean = 150 ÷ 12 = 12.5 mm per month." },
  { id: 28, question: "Which one of the following representations of cloud cover is a typical characteristic of the hot deserts?", options: ["A fully shaded circle (overcast)", "A half-shaded circle (4/8)", "A quarter-shaded circle (2/8)", "A blank/clear circle (0/8)"], correctAnswer: 3, tip: "Hot deserts have very few clouds — represented by an empty (clear) station circle." },
  { id: 29, question: "The most distinctive feature of the hot, wet equatorial climate is its ...", options: ["large annual range of temperature.", "heavy summer rainfall.", "double maxima of rainfall coinciding with equinoxes.", "distinct dry and wet seasons."], correctAnswer: 2, tip: "The sun's overhead position at the equinoxes gives equatorial regions two rainfall peaks." },
  { id: 30, question: "Which one of the following climatic regions is likely to have wiry grass?", options: ["Equatorial", "Hot desert", "Mediterranean", "Savanna"], correctAnswer: 3, tip: "Tough, wiry grass is characteristic of savanna grasslands." },
  { id: 31, question: "Lumbering in the Savanna regions has been negatively affected largely due to ...", options: ["increase in deforestation.", "lack of government's policies.", "lack of proper machinery.", "scattered tree species of the same type."], correctAnswer: 3, tip: "Savanna trees of the same species are widely scattered, making commercial lumbering uneconomic." },
  { id: 32, question: "The following tree species are all found in the Savanna region except, ...", options: ["Acacia.", "Baobab.", "Meranti.", "Mulga."], correctAnswer: 2, tip: "Meranti is a tropical equatorial rainforest tree (South-East Asia), not a savanna species." },
  { id: 33, question: "The population density of a country depends on the ...", options: ["birth rate and death rate.", "rate of population increase.", "size of the territory and the size of population.", "standard of living and urbanisation."], correctAnswer: 2, tip: "Population density = total population ÷ land area." },
  { id: 34, question: "Which one of the following countries is the least populated?", options: ["Britain", "Colombia", "Egypt", "Sweden"], correctAnswer: 3, tip: "Sweden has the smallest population of the four (about 10 million)." },
  { id: 35, question: "A world map shades densely populated areas in north-eastern USA and Western Europe. The shaded areas are densely populated mainly due to ...", options: ["agriculture.", "fishing.", "mining.", "industrialisation."], correctAnswer: 3, tip: "Heavy industrialisation in those regions has attracted large populations to industrial cities." },
  { id: 36, question: "The most critical challenge in over populated areas is ...", options: ["food shortages.", "lack of accommodation.", "lack of clothing.", "poor road network."], correctAnswer: 0, tip: "When population exceeds the area's carrying capacity, food supply becomes the most critical problem." },
  { id: 37, question: "A diagram shows houses clustered together near a road and river junction. Which one of the following settlement patterns is depicted in the diagram?", options: ["Dispersed", "Isolated", "Linear", "Nucleated"], correctAnswer: 3, tip: "Houses grouped tightly around a central feature form a nucleated settlement." },
  { id: 38, question: "What name is given to centres of commerce and finance where trade is the primary concern?", options: ["Banking towns", "Commercial towns", "Financial towns", "Market towns"], correctAnswer: 1, tip: "Towns whose main function is buying and selling are called commercial towns." },
  { id: 39, question: "Which one of the following is the greatest producer of rice in the world?", options: ["China", "India", "Indonesia", "Thailand"], correctAnswer: 0, tip: "China is currently the world's largest producer of rice." },
  { id: 40, question: "Three farming types are described: X – densely populated countries, oriental farming; Y – highly mechanised, large scale; Z – abandoning exhausted fields. Which option correctly matches Shifting cultivation, Intensive farming and Extensive farming?", options: ["Shifting=Y, Intensive=X, Extensive=Z", "Shifting=X, Intensive=Y, Extensive=Z", "Shifting=Z, Intensive=X, Extensive=Y", "Shifting=Z, Intensive=Y, Extensive=X"], correctAnswer: 2, tip: "Z is shifting cultivation, X is intensive (oriental) farming and Y is extensive (mechanised) farming." },
  { id: 41, question: "Which type of farming tends to result into low yield per hectare but high yield per individual?", options: ["Extensive mechanised farming", "Intensive subsistence farming", "Plantation farming", "Shifting cultivation"], correctAnswer: 0, tip: "Extensive mechanised farms cover huge areas — output per hectare is low but per worker is very high." },
  { id: 42, question: "Soil erosion may not be prevented by ...", options: ["contour ploughing.", "planting trees.", "ploughing grasslands.", "terracing farmland."], correctAnswer: 2, tip: "Ploughing up grasslands removes the protective cover and actually causes erosion." },
  { id: 43, question: "Which one of the following countries is the world's largest consumer of wheat?", options: ["Britain", "Canada", "Egypt", "South Africa"], correctAnswer: 2, tip: "Of these, Egypt consumes the most wheat — bread is the staple food and the country is a major wheat importer." },
  { id: 44, question: "A crop is cultivated from 35°N to 25°S, with summer temperatures of 21°C, rainfall of about 1,000 mm and 200 frost-free days. Which crop requires these growing conditions?", options: ["Cassava", "Cocoa", "Coffee", "Cotton"], correctAnswer: 3, tip: "These conditions — wide tropical range, warm summers, ~1,000 mm rainfall and frost-free harvest — match cotton." },
  { id: 45, question: "The rearing of cattle mainly for beef production is known as ...", options: ["dairying.", "horticulture.", "ranching.", "poultry."], correctAnswer: 2, tip: "Large-scale rearing of beef cattle on extensive grazing land is called ranching." },
  { id: 46, question: "Thermal electricity refers to power ...", options: ["contained in batteries.", "made from running water.", "made from solar radiation.", "made from natural gas."], correctAnswer: 3, tip: "Thermal power stations burn fossil fuels (coal, oil, natural gas) to produce steam that drives turbines." },
  { id: 47, question: "Which of the following is referred to as a 'clean' source of energy?", options: ["Geothermal energy", "Hydro energy", "Solar energy", "Wind energy"], correctAnswer: 2, tip: "Solar energy produces no emissions during use and is widely described as a clean energy source." },
  { id: 48, question: "Which of the following is not among the major factors that have promoted coal mining in South Africa? The ...", options: ["bulk of the coal is exported to earn forex.", "coal lies near the surface.", "coal is of inferior quality.", "coal occurs in very thick layers."], correctAnswer: 2, tip: "South African coal is of high quality — its inferior quality would be a hindrance, not a promoter." },
  { id: 49, question: "Which one of the following countries has the least potential in the production of hydro electricity?", options: ["France", "Germany", "Japan", "Poland"], correctAnswer: 3, tip: "Poland is largely flat with few large rivers, giving it the least hydro-electric potential of the four." },
  { id: 50, question: "Which one of the following is mined in connection with petroleum?", options: ["Asphalt", "Ethane", "Methane", "Kerosene"], correctAnswer: 0, tip: "Asphalt (bitumen) is a naturally occurring petroleum product mined alongside crude oil." },
];

geographyTests[4] = test5;

const test6: Question[] = [
  { id: 1, question: "What is the six figure grid reference of Chiswingo Ruins in the South Western part of the map?", options: ["162 777", "777 162", "787 172", "792 187"], correctAnswer: 0, tip: "Read eastings first then northings — Chiswingo Ruins lies at 162 777." },
  { id: 2, question: "What is the height of the summit of Danga Hill in grid square 1679?", options: ["9622.6 metres", "8307.0 metres", "6991.4 metres", "1315.8 metres"], correctAnswer: 3, tip: "The trig point spot height of Danga Hill reads 1,315.8 m above sea level." },
  { id: 3, question: "Which one of the squares has the most concentration of huts?", options: ["1781", "1780", "1779", "1778"], correctAnswer: 0, tip: "Square 1781 shows the densest cluster of hut symbols on the extract." },
  { id: 4, question: "Find the distance along River Poto from the western edge of the map up to the bridge in grid square 1780.", options: ["2.0 kilometres", "3.0 kilometres", "4.0 kilometres", "5.0 kilometres"], correctAnswer: 1, tip: "Measuring with a string and applying the 1:50 000 scale gives about 3.0 km." },
  { id: 5, question: "The Mazowe River generally flows from ...", options: ["north east to south west.", "south west to north east.", "north to south.", "east to west."], correctAnswer: 1, tip: "Contour heights drop from south-west toward north-east, so the river flows in that direction." },
  { id: 6, question: "According to map evidence, which one of the following services is not offered in the map extract?", options: ["Recreation services", "Sanitation services", "Education services", "Security services"], correctAnswer: 1, tip: "No sewage works or sanitation symbols appear on the extract." },
  { id: 7, question: "What is the main economic activity for Bindura?", options: ["Tourism", "Lumbering", "Fishing", "Farming"], correctAnswer: 3, tip: "Extensive cultivation symbols across the extract show farming as the main activity." },
  { id: 8, question: "Which of the following physical features is found in the above map extract?", options: ["Divide", "Flood plains", "Interlocking spurs", "Waterfalls"], correctAnswer: 2, tip: "Ridges projecting alternately into a river valley form interlocking spurs." },
  { id: 9, question: "Which of the following features is not found in grid square 1780?", options: ["Bridge", "Confluence", "Reservoir", "Settlement"], correctAnswer: 2, tip: "Square 1780 has a bridge, confluence and settlement but no reservoir symbol." },
  { id: 10, question: "What is the main vegetation type found in the central part of Bindura?", options: ["Dense bush", "Forest", "Medium bush", "Sparse bush"], correctAnswer: 2, tip: "The vegetation symbols in the central part indicate medium bush." },
  { id: 11, question: "The dominant drainage pattern in the map extract of Bindura is generally ...", options: ["dendritic.", "trellis.", "radial.", "rectangular."], correctAnswer: 0, tip: "Tributaries branching like tree limbs into the main river give a dendritic pattern." },
  { id: 12, question: "The settlement pattern south of grid line 80 is ...", options: ["clustered.", "dispersed.", "linear.", "scattered."], correctAnswer: 1, tip: "Huts spread out widely south of grid line 80 form a dispersed pattern." },
  { id: 13, question: "Which of the following latitudes is the longest?", options: ["29°S", "51°N", "60°S", "79°N"], correctAnswer: 0, tip: "Latitude circles get smaller toward the poles; 29°S is closest to the equator and therefore the longest." },
  { id: 14, question: "A jet started off from London longitude 0° at 2:00 p.m. for Lusaka longitude 30°E and took 2 hours 40 minutes to reach Lusaka. At what time did the jet arrive in Lusaka?", options: ["6:00 p.m", "6:40 p.m", "7:00 p.m", "7:40 p.m"], correctAnswer: 1, tip: "Lusaka is 2 hours ahead of London; 14:00 + 2 h + 2 h 40 min = 18:40 (6:40 p.m.)." },
  { id: 15, question: "At which angle is the earth's axis inclined resulting in the change of seasons and length of day?", options: ["23½°", "66½°", "90°", "360°"], correctAnswer: 0, tip: "The Earth's axis is tilted at 23½° from the vertical, causing the seasons." },
  { id: 16, question: "Which of the following would be a positive impact of the aftermath of the feature above?", options: ["Availability of fertile soils", "Availability of fish in nearby streams", "Destruction of vegetation", "Relocation of wild animals"], correctAnswer: 0, tip: "Weathered lava breaks down into rich, fertile volcanic soils." },
  { id: 17, question: "The hot lavas that are highly fluid, rich in iron and magnesium are called ...", options: ["acid lava.", "basic lava.", "cinder cones.", "lava plains."], correctAnswer: 1, tip: "Basic (basaltic) lava is low in silica, rich in iron and magnesium and very fluid." },
  { id: 18, question: "A seismography is used to determine the ...", options: ["magnitude of the earthquake.", "intensity of the earthquake.", "source of earthquake.", "thickness of the earthquake."], correctAnswer: 0, tip: "A seismograph records seismic waves and is used to measure the magnitude of earthquakes." },
  { id: 19, question: "What type of mass movement is shown in the diagram above?", options: ["Solifluction", "Soil flow", "Soil creep", "Landslide"], correctAnswer: 3, tip: "Land slumping down in sections along a slip surface is a landslide." },
  { id: 20, question: "Which one of the following is not a characteristic feature of a youthful valley?", options: ["Ox-bow lake", "Pot holes", "V-shaped valley", "Waterfall"], correctAnswer: 0, tip: "Ox-bow lakes form in mature/old-age stages, not in youthful valleys." },
  { id: 21, question: "Which of the following is not an agent of weathering?", options: ["Waterfalls", "Tsunami", "Animals", "Air pressure"], correctAnswer: 1, tip: "A tsunami is an agent of erosion, not of weathering." },
  { id: 22, question: "Which one of the following features of erosion is commonly found in the lower course of a river?", options: ["Cataract", "Distributary", "Interlocking Spur", "River capture"], correctAnswer: 1, tip: "Distributaries branch from the main channel as the river nears its mouth." },
  { id: 23, question: "The volcanoes that have erupted before and still have potential to erupt in future are referred to as ...", options: ["active.", "dormant.", "extinct.", "viscous."], correctAnswer: 1, tip: "A dormant volcano has erupted in the past and may erupt again." },
  { id: 24, question: "The diagram above shows the formation of ...", options: ["a recumbent fold.", "a simple fold.", "an asymmetric fold.", "an overfold."], correctAnswer: 0, tip: "When the limbs of a fold lie nearly horizontal, the fold is called recumbent." },
  { id: 25, question: "The low pressure belt along the Equator is referred to as ...", options: ["doldrums.", "horse latitude.", "polar high.", "temperate latitude."], correctAnswer: 0, tip: "The equatorial low-pressure belt of light, calm winds is called the doldrums." },
  { id: 26, question: "The rate of decrease in temperature with altitude is called ...", options: ["convection.", "lapse rate.", "insolation.", "solar radiation."], correctAnswer: 1, tip: "The fall of temperature with height in the atmosphere is the lapse rate." },
  { id: 27, question: "In which hemisphere is the cyclone above found?", options: ["Along 0° latitude", "Along 60° north latitude", "Along 60° south latitude", "Around polar regions"], correctAnswer: 1, tip: "An anticlockwise rotating cyclone with these isobars is typical of 60° N." },
  { id: 28, question: "What type of rainfall results from the meeting of two different air masses?", options: ["Acid rain", "Convectional rain", "Frontal rain", "Orographic rain"], correctAnswer: 2, tip: "When warm and cold air masses meet, the warm air is forced up to form frontal rain." },
  { id: 29, question: "Area X experiences lower temperatures than Y due to ...", options: ["high latitude.", "low latitude.", "high rainfall.", "low rainfall."], correctAnswer: 0, tip: "X is in higher latitude where the sun's rays strike at a low angle, giving cooler temperatures." },
  { id: 30, question: "Which one of the following is not a characteristic of the vegetation of the equatorial region?", options: ["Cone shaped trees", "Evergreen broad leaved", "Layer growth arrangement", "Little undergrowth"], correctAnswer: 0, tip: "Cone-shaped trees are typical of cold coniferous forests, not equatorial rainforest." },
  { id: 31, question: "The shaded climatic region on the map is ...", options: ["Equatorial.", "Hot desert.", "Mediterranean.", "Savannah."], correctAnswer: 3, tip: "The shaded belt north and south of the equatorial zone in Africa is the savannah." },
  { id: 32, question: "The following are the characteristics of the vegetation of the shaded area except ...", options: ["trees are umbrella shaped.", "trees do not shed their leaves.", "trees have big trunks.", "trees have long tap roots."], correctAnswer: 1, tip: "Savanna trees DO shed their leaves during the dry season to conserve water." },
  { id: 33, question: "Which country below has the highest population?", options: ["China", "India", "Indonesia", "Japan"], correctAnswer: 0, tip: "China has the largest population of the four countries listed." },
  { id: 34, question: "The following are factors influencing population distribution. Which one of them is a physical factor?", options: ["Government policy", "Rainfall", "Relief", "Temperature"], correctAnswer: 2, tip: "Relief (the shape of the land) is a physical factor that strongly affects where people settle." },
  { id: 35, question: "Which of the following is a characteristic of a developing country?", options: ["High literacy levels", "Low birth rate", "Low death rate", "Low life expectancy"], correctAnswer: 3, tip: "Developing countries typically have low life expectancy due to poor health services." },
  { id: 36, question: "The term used to describe an increase in the number of people living in towns and cities is ...", options: ["conurbation.", "urban drift.", "urbanisation.", "urban sprawl."], correctAnswer: 2, tip: "Urbanisation is the growing share of a population living in towns and cities." },
  { id: 37, question: "Why are some of the areas in the arid regions highly populated?", options: ["Availability of animals and fruits", "Availability of camels", "Developed transport system", "Presence of oasis"], correctAnswer: 3, tip: "Oases provide reliable water in deserts and attract dense settlement." },
  { id: 38, question: "Fertility rate refers to the ...", options: ["average number of children a woman is able to have during her child bearing age.", "average number of children born alive by a woman.", "number of children born dead by a woman.", "number of years a woman stays without having a child."], correctAnswer: 0, tip: "Fertility rate measures the average number of children a woman can bear during her reproductive years." },
  { id: 39, question: "Which of the following crops is a fibre?", options: ["Barley", "Coffee", "Cotton", "Rubber"], correctAnswer: 2, tip: "Cotton is grown for its fibre, used to make textiles." },
  { id: 40, question: "Which of the following farming techniques is sustainable in nature?", options: ["Chitemene farming", "Commercial farming", "Conservative farming", "Strip farming"], correctAnswer: 2, tip: "Conservation farming maintains soil fertility long-term and is therefore sustainable." },
  { id: 41, question: "A type of agriculture is said to keep soils at high fertility levels, practised in densely populated areas with subsequently high yields per hectare. What type of agriculture is this?", options: ["Extensive mechanised agriculture", "Intensive subsistence agriculture", "Plantation agriculture", "Primitive subsistence agriculture"], correctAnswer: 1, tip: "Intensive subsistence farming uses small plots, much labour and manure to give very high yields per hectare." },
  { id: 42, question: "Which one of the following countries is known as the corn belt?", options: ["America", "Brazil", "France", "South Africa"], correctAnswer: 0, tip: "The Corn Belt is a region of the central United States dominated by maize cultivation." },
  { id: 43, question: "It is a universal beverage and widely consumed. Which of the following crops is referred to in this statement?", options: ["Cocoa", "Coffee", "Millet", "Tea"], correctAnswer: 3, tip: "Tea is the most widely consumed beverage in the world after water." },
  { id: 44, question: "Which of the following agriculture activities is commonly practised near urban areas?", options: ["Cattle ranching", "Cereal cultivation", "Dairy farming", "Plantation farming"], correctAnswer: 2, tip: "Dairy farming locates near cities so milk reaches markets quickly while still fresh." },
  { id: 45, question: "To help replenish soil fertility, which one of the following farming techniques would be mostly appropriate?", options: ["Cover cropping", "Crop rotation", "Mulching", "Terracing"], correctAnswer: 1, tip: "Crop rotation alternates nutrient-restoring legumes with other crops, replenishing soil fertility." },
  { id: 46, question: "The largest supply of electricity in the world comes from ...", options: ["geo thermal.", "hydro.", "thermal.", "wind."], correctAnswer: 2, tip: "Most of the world's electricity is generated by thermal (fossil-fuel) power stations." },
  { id: 47, question: "Which of the following sources of electricity has unlimited divisibility?", options: ["Biomas", "Hydro", "Thermal", "Wind"], correctAnswer: 3, tip: "Wind power can be tapped at any scale anywhere wind blows — it has unlimited divisibility." },
  { id: 48, question: "Coal fields are usually located ...", options: ["in association with igneous rocks.", "in association with sedimentary rocks.", "in industrial regions.", "near valleys."], correctAnswer: 1, tip: "Coal forms from compressed plant remains in sedimentary rock layers." },
  { id: 49, question: "The increase in the world oil prices has resulted in the following except ...", options: ["greater wealth for oil nations.", "high prices for manufactured goods.", "increase in environmental pollution.", "world-wide inflation."], correctAnswer: 2, tip: "Higher oil prices tend to reduce oil consumption, so they don't directly increase pollution." },
  { id: 50, question: "Which use of petroleum is essential for the smooth generation of machines?", options: ["Lubrication", "Motor fuel", "Source of power", "Surfacing roads"], correctAnswer: 0, tip: "Lubricating oils derived from petroleum reduce friction and allow machines to run smoothly." },
];

