const test7: Question[] = [
  { id: 1, question: "Find the six figure grid reference of the spot height 1126 South of Glendale staff quarters.", options: ["801 959", "819 962", "959 801", "951 809"], correctAnswer: 0, tip: "Eastings first then northings — spot height 1126 is at 801 959." },
  { id: 2, question: "What is the vertical interval of the map of Glendale?", options: ["10 metres", "20 metres", "30 metres", "40 metres"], correctAnswer: 1, tip: "Contour lines on the Glendale extract are drawn at 20 m intervals." },
  { id: 3, question: "Name the hill that is on the South Eastern part of Glendale.", options: ["Clifton", "Domboshawa", "Kasipa", "Virginia South"], correctAnswer: 3, tip: "Virginia South Hill is labelled in the south-eastern part of the map." },
  { id: 4, question: "What is the bearing of Kilmer in grid square 9083 from the school in grid square 9479?", options: ["42°", "130°", "230°", "318°"], correctAnswer: 2, tip: "Measured clockwise from north, the bearing of Kilmer from the school is about 230°." },
  { id: 5, question: "What is the general description of the relief at Glendale?", options: ["Flat", "Gentle", "Hilly", "Plateau"], correctAnswer: 2, tip: "The closely spaced contours and many named hills indicate hilly relief." },
  { id: 6, question: "What is the distance of the road from the Dip Tank at footbridge in grid square 9183 to the T-junction in grid square 9381?", options: ["2.0km", "2.5km", "3.1km", "3.5km"], correctAnswer: 2, tip: "Measuring along the road with a string and applying the 1:50 000 scale gives about 3.1 km." },
  { id: 7, question: "The height of the trigonometrical station in grid square 9874 is ...", options: ["1156 metres.", "1218 metres.", "1614.1 metres.", "1620.1 metres."], correctAnswer: 2, tip: "The trig point in square 9874 reads 1614.1 m above sea level." },
  { id: 8, question: "What type of vegetation is predominant in the South West Corner of the map of Glendale?", options: ["Medium bush", "Open grassland", "Sparse bush", "Very dense bush"], correctAnswer: 0, tip: "The vegetation symbols in the south-west corner indicate medium bush." },
  { id: 9, question: "According to the map evidence, what social services are offered by Glendale Town?", options: ["Burial site, health and market", "Education, health and recreation", "Education, health and security", "Market, health and recreation"], correctAnswer: 2, tip: "Symbols for a school, hospital and police station show education, health and security." },
  { id: 10, question: "According to the map evidence, what is the settlement pattern for Glendale Town?", options: ["Dispersed", "Linear", "Nucleated", "Random"], correctAnswer: 2, tip: "Buildings are clustered tightly together around the town centre — a nucleated pattern." },
  { id: 11, question: "Identify the physical feature in grid square 9385.", options: ["Confluence", "Distributary", "Lake", "Swamp"], correctAnswer: 0, tip: "Two streams meeting at a point in square 9385 form a confluence." },
  { id: 12, question: "According to the map evidence, what is the major economic activity of Glendale?", options: ["Agriculture", "Fishing", "Lumbering", "Manufacturing"], correctAnswer: 0, tip: "Extensive cultivation symbols across the map show agriculture as the main activity." },
  { id: 13, question: "During the under 20 World Cup soccer Competition in South Korean Republic (120°E) a match between England and Zambia commenced at 15:00 hours. What was the time in Zambia (30°E) when the match commenced?", options: ["06:00 hours", "07:00 hours", "08:00 hours", "09:00 hours"], correctAnswer: 3, tip: "Difference in longitude = 90° = 6 hours; Zambia is west of Korea, so 15:00 − 6 h = 09:00." },
  { id: 14, question: "What is the approximate straight line distance between Cairo (30°N) and Bulawayo (20°S)?", options: ["600km", "1,600km", "3,300km", "5,550km"], correctAnswer: 3, tip: "Total latitude difference is 50°; 50 × 111 km ≈ 5,550 km." },
  { id: 15, question: "The permanent tilt of the earth's axis and revolution of the earth in its orbit together cause ...", options: ["day and night.", "deflection of the wind.", "difference in times between places on different meridians.", "varying lengths of the day and night at different times of the year."], correctAnswer: 3, tip: "Axis tilt plus revolution gives the seasons and the changing day-length." },
  { id: 16, question: "The feature above (Block A moving up and Block B moving down along a line) is most likely to have been caused by ...", options: ["erosion.", "faulting.", "folding.", "jointing."], correctAnswer: 1, tip: "Vertical movement of blocks along a fracture is faulting." },
  { id: 17, question: "Which of the following types of weathering is common in Temperate Regions and in high mountains?", options: ["Exfoliation", "Frost action", "Hydration", "Oxidation"], correctAnswer: 1, tip: "Repeated freezing and thawing of water in cracks (frost action) shatters rocks in cold regions." },
  { id: 18, question: "In the diagram of igneous intrusions, the feature labelled S is ...", options: ["batholiths.", "dyke.", "laccolith.", "phacolith."], correctAnswer: 2, tip: "A dome-shaped intrusion that pushes overlying strata upward is a laccolith." },
  { id: 19, question: "Which of the points A, B, C or D represents the plain course of a river?", options: ["A — large angular rocks (source)", "B — smaller rounded rocks", "C — even smaller rounded rocks", "D — very small well-rounded particles (deposition)"], correctAnswer: 3, tip: "The plain (lower) course is where fine, well-rounded sediment is deposited." },
  { id: 20, question: "What type of mass movement is shown in the diagram (slow downslope movement of soil over parent rock)?", options: ["Landslide", "Mudflow", "Rock fall", "Soil creep"], correctAnswer: 3, tip: "Very slow, almost imperceptible downhill movement of soil is soil creep." },
  { id: 21, question: "What river features are represented by M and N in the delta diagram?", options: ["Estuary and Lagoon", "Estuary and Ox-bow lake", "Lagoon and Distributary", "Ox-bow lake and Distributary"], correctAnswer: 2, tip: "At a delta, M is the lagoon trapped behind the bars and N is a distributary channel." },
  { id: 22, question: "What environmental hazard has affected the shaded area in North Africa?", options: ["Acidic rain", "Drought", "Floods", "Tropical storms"], correctAnswer: 1, tip: "The Sahel/North Africa region is regularly affected by severe drought." },
  { id: 23, question: "Which one of the following represents a cyclone in the Southern Hemisphere?", options: ["Anticlockwise rotation with low pressure in the centre", "Clockwise rotation with low pressure in the centre", "Clockwise rotation with high pressure in the centre", "Anticlockwise rotation with high pressure in the centre"], correctAnswer: 1, tip: "In the Southern Hemisphere, cyclones (low-pressure systems) rotate clockwise around the low centre." },
  { id: 24, question: "Which statement is correct about the climatic data above?", options: ["It has relatively high temperature in summer.", "It has relatively uniform temperature throughout the year.", "It has very high rainfall throughout the year.", "Most of the rains are received in summer."], correctAnswer: 3, tip: "The chart shows a clear summer rainfall maximum, typical of tropical climates." },
  { id: 25, question: "What vegetation type best suits the climatic data being presented?", options: ["Evergreen forests, palm trees and deciduous trees", "Evergreen oak, pine and wiry grass", "Scrub, drought resistant and cacti", "Tall grass, scattered trees and thorny bushes"], correctAnswer: 3, tip: "Summer-rain tropical climates support savanna vegetation — tall grass with scattered trees." },
  { id: 26, question: "The earth's atmosphere gets ...", options: ["thicker as altitude increases.", "thicker as latitude decrease.", "thinner as altitude decreases.", "thinner as altitude increases."], correctAnswer: 3, tip: "Air density decreases with height, so the atmosphere thins as altitude increases." },
  { id: 27, question: "Which of the following regions is the poorest in biodiversity?", options: ["Equatorial", "Hot deserts", "Mediterranean", "Savanna"], correctAnswer: 1, tip: "Hot deserts have the harshest conditions and therefore the fewest species." },
  { id: 28, question: "Which of the following areas A, B, C or D experiences less rainfall?", options: ["A", "B", "C", "D"], correctAnswer: 1, tip: "The area covering the Sahara (B) receives the least rainfall in Africa." },
  { id: 29, question: "Which of the following is the characteristic of the vegetation in area C?", options: ["It is drought resistant", "Many plants have thick stems", "Trees grow in pure stands", "Trees grow very tall"], correctAnswer: 3, tip: "Area C lies in the equatorial belt where trees grow very tall in dense rainforest." },
  { id: 30, question: "The term hydrophytic is associated with the ... climate.", options: ["Equatorial", "Hot desert", "Mediterranean", "Savanna"], correctAnswer: 0, tip: "Hydrophytes are water-loving plants typical of the wet equatorial climate." },
  { id: 31, question: "What type of vegetation springs up when the virgin Tropical Rainforest have been cleared and abandoned?", options: ["Creepers", "Evergreen trees", "Lianas", "Mangrove forests"], correctAnswer: 0, tip: "Cleared rainforest is quickly colonised by fast-growing creepers and secondary growth." },
  { id: 32, question: "The extreme diurnal range of temperature is characteristic of the ...", options: ["Equatorial climate.", "Hot desert climate.", "Mediterranean climate.", "Sudan climate."], correctAnswer: 1, tip: "Hot deserts heat strongly by day and cool sharply at night, giving a very large diurnal range." },
  { id: 33, question: "How can traffic congestion be reduced in large cities?", options: ["Constructing by pass routes", "Creating single lanes", "Encouraging use of private vehicles", "Impounding over speeding vehicles"], correctAnswer: 0, tip: "By-pass routes divert through-traffic away from city centres, reducing congestion." },
  { id: 34, question: "Which one of the following is not a push factor in the rural-urban migration process?", options: ["Decrease in the standard of living", "High dependency ratio", "High gross national product per capital income", "Low levels of national development"], correctAnswer: 2, tip: "High GNP per capita is a pull factor (attractive condition), not a push factor." },
  { id: 35, question: "In the table (Z 13/12, Y 16/9, X 50/16, W 54/12), which one of the following is correct?", options: ["Country W is Zimbabwe while Y is Nigeria", "Country X is Nigeria while Z is United Kingdom", "Country Y is Zimbabwe while X is Nigeria", "Country Z is the United States of America while Y is Zimbabwe"], correctAnswer: 1, tip: "X has very high birth and death rates (Nigeria); Z's rates are very low (UK)." },
  { id: 36, question: "What type of settlement is shown above (houses spread thinly across rural land)?", options: ["dispersed", "isolated", "linear", "nucleated"], correctAnswer: 0, tip: "Houses spread out widely across the countryside form a dispersed settlement." },
  { id: 37, question: "Towns tend to grow and expand towards each other till they eventually merge. This is called ...", options: ["confluence town.", "conurbation.", "nodal town.", "satellite town."], correctAnswer: 1, tip: "When neighbouring towns grow into one continuous urban area, the result is a conurbation." },
  { id: 38, question: "Which one of the following countries has the highest fertility rate?", options: ["Egypt", "Germany", "Italy", "United States of America"], correctAnswer: 0, tip: "Egypt, a developing country, has the highest fertility rate among the four." },
  { id: 39, question: "Which one of the following is not a characteristic of plantation farming?", options: ["It is capital intensive.", "It is generally a monoculture crop.", "It is not highly mechanised.", "It occupies large areas of land."], correctAnswer: 2, tip: "Plantation farming IS highly mechanised — option C is the false statement." },
  { id: 40, question: "Dairy farming is usually practised near large city areas because ...", options: ["dairy products are perishable.", "grass is greener in urban areas.", "only urban areas are suitable for dairy animals.", "rural dwellers do not consume dairy products."], correctAnswer: 0, tip: "Milk and dairy products spoil quickly, so they are produced close to urban markets." },
  { id: 41, question: "Which of the following crops are grown under shifting cultivation?", options: ["Barley and millet", "Cassava and maize", "Sorghum and rice", "Wheat and ground nuts"], correctAnswer: 1, tip: "Cassava and maize are the typical food crops grown under shifting cultivation." },
  { id: 42, question: "Which one of the following describes extensive farming?", options: ["Highly mechanised", "High use of draught power", "High use of human labour", "High yield per hectare"], correctAnswer: 0, tip: "Extensive farming covers very large areas and relies on heavy mechanisation." },
  { id: 43, question: "Which one of the following is a geographical requirement for the successful growth of maize?", options: ["Average rainfall of 650mm – 1000mm", "Average temperature of above 16°C", "Rich alluvial soils with an impoverished sub-soil", "Thick clay soil on gentle slope"], correctAnswer: 0, tip: "Maize grows best with moderate rainfall of about 650–1000 mm per year." },
  { id: 44, question: "A geologist prospecting and surveying for oil would most likely consider ...", options: ["gently folded anticline strata.", "zones of igneous rocks.", "zones of impervious rocks.", "zones of metamorphic rocks."], correctAnswer: 0, tip: "Oil collects in the crests of gently folded anticlines beneath impervious cap rocks." },
  { id: 45, question: "For successful Hydro Electric Power development, the following factors are essential except ...", options: ["convenient transport.", "large domestic market.", "sufficient volume of water.", "steep gradient."], correctAnswer: 0, tip: "Convenient transport is not essential — HEP can be transmitted by power lines from remote sites." },
  { id: 46, question: "The highest potential which Africa has on solar production is based on the abundance of ...", options: ["forests.", "minerals.", "cloud cover.", "sunshine."], correctAnswer: 3, tip: "Africa lies mostly in the tropics with abundant sunshine — ideal for solar power." },
  { id: 47, question: "Which among the following countries is a major importer of coal?", options: ["China", "India", "Japan", "Malaysia"], correctAnswer: 2, tip: "Japan has very limited domestic coal reserves and imports large quantities for industry." },
  { id: 48, question: "What type of energy produced by human and animal waste is used for lighting, cooking and generating electricity?", options: ["Biogas", "Ethanol", "Methane", "Petroleum"], correctAnswer: 0, tip: "Biogas is produced by the anaerobic digestion of human and animal waste." },
  { id: 49, question: "Which one of the following is not a fossil fuel?", options: ["Biomass", "Coal", "Petroleum", "Uranium"], correctAnswer: 0, tip: "Biomass is renewable plant/animal matter — not a fossil fuel." },
  { id: 50, question: "What type of energy has propelled the success in manufacturing of valuable machinery, electrical appliances in Switzerland?", options: ["Hydro-electric power", "Thermal power", "Nuclear power", "Geothermal power"], correctAnswer: 0, tip: "Switzerland's mountainous terrain and rivers give it abundant hydro-electric power." },
];

