const test8: Question[] = [
  { id: 1, question: "Find the six figure grid reference of Gobo sulphur springs.", options: ["265 632", "266 637", "632 264", "637 266"], correctAnswer: 1, tip: "Eastings first then northings — Gobo sulphur springs lies at 266 637." },
  { id: 2, question: "What is the approximate distance of Deka river from spot height 714 in grid square 3168 to the confluence with Katuna River in grid square 3370?", options: ["1.5 kilometres", "2.0 kilometres", "2.5 kilometres", "3.5 kilometres"], correctAnswer: 3, tip: "Measuring along the river with a string and applying the 1:50 000 scale gives about 3.5 km." },
  { id: 3, question: "Find the bearing of the water reservoir in grid square 3864 from the spot height 806 in grid square 4365.", options: ["75°", "105°", "255°", "300°"], correctAnswer: 2, tip: "The reservoir lies south-west of the spot height; clockwise from north the bearing is about 255°." },
  { id: 4, question: "Which of the following grid squares has the least density of streams?", options: ["3356", "3357", "3358", "3359"], correctAnswer: 3, tip: "Square 3359 shows the fewest blue stream lines on the extract." },
  { id: 5, question: "What economic activity is associated with the map extract above?", options: ["Fishing", "Forestry", "Mining", "Tourism"], correctAnswer: 2, tip: "Mine shafts, dumps and the railway in the extract show that mining is the activity." },
  { id: 6, question: "According to map evidence, what is the general drainage pattern of Hwange West?", options: ["Dendritic", "Radial", "Rectangle", "Trellis"], correctAnswer: 0, tip: "Tributaries branch into the main river like the limbs of a tree — a dendritic pattern." },
  { id: 7, question: "What is the height above sea level of the peak of Mavinga Hill in grid square 4173?", options: ["820.6 metres", "895.4 metres", "1000 metres", "1038 metres"], correctAnswer: 3, tip: "The trig point on Mavinga Hill reads 1038 m above sea level." },
  { id: 8, question: "According to map evidence, the major use of the railway network is to transport ...", options: ["building materials.", "farm products.", "fish.", "minerals."], correctAnswer: 3, tip: "The railway links to the Hwange coal mining area, so its main use is to transport minerals." },
  { id: 9, question: "Apart from coal mining, what other economic activity is prominent in the extract above?", options: ["Cultivation", "Game ranching", "Orchard and plantation", "Timber production"], correctAnswer: 1, tip: "Hwange National Park lies in the area, making game ranching/wildlife conservation prominent." },
  { id: 10, question: "What natural feature is found in grid square 2572?", options: ["Gorge", "Meander", "Rapid", "Waterfall"], correctAnswer: 1, tip: "The river bends sharply in square 2572, forming a meander." },
  { id: 11, question: "What type of settlement is Mandama Extension?", options: ["Dispersed", "Linear", "Isolated", "Nucleated"], correctAnswer: 3, tip: "Buildings clustered tightly together form a nucleated settlement." },
  { id: 12, question: "In which direction is river Deka flowing?", options: ["North east", "North west", "South east", "South west"], correctAnswer: 1, tip: "Contour heights drop toward the north-west, so the Deka flows in that direction." },
  { id: 13, question: "A presidential jet destined for Lusaka (30°E), Zambia, leaves New York (74°W) at 23:04 hours on Tuesday. If it is a 15:00 hours flight, what time is the jet expected to land in Lusaka?", options: ["08:04 hours on Tuesday", "07:48 hours on Wednesday", "14:04 hours on Wednesday", "21:00 hours on Wednesday"], correctAnswer: 3, tip: "Lusaka is about 6 h 56 min ahead of New York; 23:04 (Tue) + 6 h 56 min + 15 h ≈ 21:00 (Wed)." },
  { id: 14, question: "Which of the following statements is correct about the earth's revolution?", options: ["The revolution of the earth results into day and night.", "The summer solstice is experienced when the sun is vertically overhead at the Tropic of Capricorn (23½°S).", "The sun is never overhead beyond the tropics at any time of the year.", "The winter solstice is experienced when the sun is vertically overhead at the Tropic of Cancer (23½°N)."], correctAnswer: 2, tip: "The sun's vertical rays are confined to the tropics; beyond them it is never directly overhead." },
  { id: 15, question: "The layer of the earth that is mainly composed of very dense rocks that are rich in olivine is the ...", options: ["barysphere.", "hydrosphere.", "lithosphere.", "mesosphere."], correctAnswer: 0, tip: "The barysphere (the dense interior of the earth) is rich in heavy minerals such as olivine." },
  { id: 16, question: "What feature is shown above (down-cutting reducing an original surface to isolated highlands)?", options: ["Block mountain", "Fold mountain", "Residual mountain", "Volcanic mountain"], correctAnswer: 2, tip: "When erosion wears down a plateau leaving isolated highlands, the result is a residual mountain." },
  { id: 17, question: "The upfolds in the earth's crust due to compressional forces are called ...", options: ["anticlines.", "nappe.", "overfolds.", "synclines."], correctAnswer: 0, tip: "An anticline is the upfold (arch) produced when rocks are squeezed together." },
  { id: 18, question: "The water discharge channels shown in the diagram above are known as ...", options: ["distributaries.", "ox-bow lakes.", "river rejuvenation.", "tributaries."], correctAnswer: 0, tip: "Channels that branch out from the main river across a delta are distributaries." },
  { id: 19, question: "At which stage of a river will the feature shown above be formed?", options: ["Mountain stage", "River mouth", "River source", "Valley course"], correctAnswer: 1, tip: "Distributaries form where the river enters the sea — at the river mouth (delta)." },
  { id: 20, question: "The volcanic feature that forms when a mass of magma cuts across a bedding plane is called a ...", options: ["batholith.", "dyke.", "laccolith.", "sill."], correctAnswer: 1, tip: "A dyke is an intrusion that cuts vertically across the bedding planes of rocks." },
  { id: 21, question: "What feature is shown in the diagram (boiling water and steam ejected from underground)?", options: ["Fountain", "Geyser", "Hot spring", "Steam"], correctAnswer: 1, tip: "A geyser intermittently ejects hot water and steam high into the air." },
  { id: 22, question: "The gradual disintegration of rocks by atmospheric forces is referred to as ...", options: ["deposition.", "erosion.", "transportation.", "weathering."], correctAnswer: 3, tip: "In-situ breakdown of rock by atmospheric agents (without movement) is weathering." },
  { id: 23, question: "What type of natural vegetation is associated with station Y (very high temperatures, very little rainfall)?", options: ["Date palms and cacti", "Evergreen trees and mangroves", "Tall grass with oak", "Teak forest and shrubs"], correctAnswer: 0, tip: "The hot, dry totals (≈150 mm) describe a hot desert — date palms and cacti." },
  { id: 24, question: "Which climatic region is referred to as the 'orchard lands' of the world?", options: ["Equatorial region", "Hot desert region", "Mediterranean region", "Savannah region"], correctAnswer: 2, tip: "The Mediterranean region is famous for fruit orchards (citrus, olives, grapes)." },
  { id: 25, question: "Which one of the following is a climatic characteristic of the shaded area (Sahara)?", options: ["Cloudless skies", "High humidity", "Very high annual temperature range", "Very low diurnal range temperature"], correctAnswer: 0, tip: "Hot deserts are dominated by descending dry air, giving cloudless skies." },
  { id: 26, question: "Plants adapt to the climate of the shaded area except by ...", options: ["growing long tap roots.", "growing waxy leaves.", "producing seeds that do not lie dormant.", "storing water in the stem."], correctAnswer: 2, tip: "Desert seeds DO lie dormant for long periods, sprouting only after rare rains." },
  { id: 27, question: "The area marked E (coast with cold Benguela current and warm desert) will experience ...", options: ["convectional rainfall.", "cyclonic rainfall.", "fog.", "mist."], correctAnswer: 2, tip: "Warm air drifting over the cold Benguela current condenses into thick coastal fog." },
  { id: 28, question: "What type of vegetation is typical of climatic conditions with winter rains and summer droughts?", options: ["Cacti, thorn bushes, date palms", "Cork oak, cedar, cypresses", "Mahogany, ebony, orchids", "Teak, Sal, bamboo"], correctAnswer: 1, tip: "Mediterranean climates produce cork oak, cedar and cypress vegetation." },
  { id: 29, question: "The natural vegetation in the wet equatorial climate does not occur in pure stands. What does the term 'pure stand' mean?", options: ["Vegetation has a variety of evergreen trees.", "Vegetation occurs in a distinct layer arrangement.", "Vegetation of a mixed species found in the same area.", "Vegetation consisting of trees of the same species growing together."], correctAnswer: 3, tip: "A pure stand is an area dominated by trees of one and the same species." },
  { id: 30, question: "Which one of the settlements A, B, C or D would experience the highest atmospheric pressure?", options: ["A — at sea level", "B — low slope", "C — middle slope", "D — top of high land"], correctAnswer: 0, tip: "Atmospheric pressure is highest at the lowest altitude — settlement A at sea level." },
  { id: 31, question: "From which climatic region would the above data be drawn (rainfall total 864 mm with sharp summer max in July–August)?", options: ["Equatorial region", "Mediterranean region", "Tropical continental", "Tropical monsoon"], correctAnswer: 3, tip: "A heavy concentrated summer rainfall maximum is the signature of the tropical monsoon climate." },
  { id: 32, question: "How does vegetation adapt to the climatic conditions shown above?", options: ["Trees are deciduous, long tap roots and broad trunks.", "Trees are halophytic, have long roots and thick succulent stems.", "Trees are xerophytic, short branches with few leaves and have no shade.", "Trees have broad leaves and slender trunks."], correctAnswer: 0, tip: "Monsoon forests are deciduous, with long tap roots and broad trunks to survive the dry season." },
  { id: 33, question: "Population density refers to ...", options: ["average living standards of people in a given area.", "number of people living in a given area of land.", "total population of a country in relation to inhabited land area of that country.", "total population of a region in relation to the area's productivity."], correctAnswer: 1, tip: "Population density = number of people per unit area of land." },
  { id: 34, question: "The following are types of rural settlement patterns except ...", options: ["dispersed.", "isolated.", "linear.", "nucleated."], correctAnswer: 1, tip: "Isolated is not classed as a recognised rural settlement pattern." },
  { id: 35, question: "Which one of the following is not a problem associated with over population?", options: ["A decline in health standards", "A rapid population increase", "High rate of unemployment", "Shortage of workforce"], correctAnswer: 3, tip: "Over-populated areas have an excess of workers, not a shortage of workforce." },
  { id: 36, question: "Which of the shaded areas marked A, B, C and D has low population density due to arid climatic conditions?", options: ["A", "B", "C", "D"], correctAnswer: 1, tip: "Shaded area B covers the world's hot deserts — low density due to aridity." },
  { id: 37, question: "Which of the areas A, B, C or D practices extensive cereal cultivation?", options: ["A", "B", "C", "D"], correctAnswer: 2, tip: "Area C covers the prairies/steppes where extensive wheat cultivation is practised." },
  { id: 38, question: "In Australia, beef cattle ranching is difficult to fully develop due to ...", options: ["great distances of the cattle farms from the Eastern coastal towns.", "high competition from outside Australia.", "high tsetse infestation which causes trypanosomiasis.", "Reliable heavy rainfall that makes pasture growth difficult."], correctAnswer: 0, tip: "Australian beef ranches lie far inland, far from the coastal markets and ports." },
  { id: 39, question: "Truck farming is commonly practiced in the United States of America. The other name for truck farming is ...", options: ["fruit farming.", "horticulture.", "market gardening.", "sericulture."], correctAnswer: 2, tip: "Truck farming is the American term for market gardening — vegetables for nearby city markets." },
  { id: 40, question: "The least grown cereal crop in Africa is ...", options: ["Maize.", "Millet.", "Sorghum.", "Wheat."], correctAnswer: 3, tip: "Wheat needs cool temperate conditions and is the least widely grown cereal in Africa." },
  { id: 41, question: "Ginning is one of the processes used in the manufacture of cotton yarn. This process refers to the ...", options: ["gathering of cotton bolls from the plant.", "joining of the cotton fibre to form a continuous thread.", "separation of the seeds from the cotton fibre.", "washing of the cotton fibre."], correctAnswer: 2, tip: "Ginning separates the cotton seeds from the fibre (lint)." },
  { id: 42, question: "Atomic power is derived from the mineral called ...", options: ["bauxite.", "felspar.", "graphite.", "uranium."], correctAnswer: 3, tip: "Uranium is the radioactive mineral used as fuel for atomic (nuclear) power." },
  { id: 43, question: "In which of the following are oil traps likely to occur? ... impervious rock layers.", options: ["Anticlines above", "Anticlines below", "Synclines above", "Synclines below"], correctAnswer: 1, tip: "Oil rises and is trapped in anticlines below impervious cap rocks." },
  { id: 44, question: "Most of the oil in Canada is drilled ...", options: ["around the St. Lawrence Great Lakes region.", "in the Alberta province.", "in the North-West Territory.", "on the shores of the Hudson Bay."], correctAnswer: 1, tip: "Alberta's oil sands and conventional fields make it Canada's main oil-producing province." },
  { id: 45, question: "Which one of the following basic requirements in the generation of Hydro-electricity is the least essential?", options: ["Heavy capital outlay", "Large international market", "Steep slope", "Sufficient volume of water"], correctAnswer: 1, tip: "An international market is not required — HEP can supply purely domestic needs." },
  { id: 46, question: "The world's leading coal producer among the following countries is ...", options: ["China.", "France.", "Japan.", "South Africa."], correctAnswer: 0, tip: "China produces and consumes the most coal in the world." },
  { id: 47, question: "Which one of the following is a disadvantage of wind energy? It ...", options: ["is a cheap source of energy.", "is an exhaustible source.", "pollutes the environment.", "produces low energy output."], correctAnswer: 3, tip: "Wind turbines produce a relatively low and variable energy output." },
  { id: 48, question: "Which one is the most effective and efficient form of energy in the world?", options: ["Geothermal power", "Hydro-electric power", "Solar energy", "Wind energy"], correctAnswer: 1, tip: "Hydro-electric power has the highest efficiency and reliability of these renewables." },
  { id: 49, question: "At a Hydro-electric Power Station, what directly converts potential energy in water to electricity?", options: ["Generator", "Penstocks", "Transformers", "Turbines"], correctAnswer: 3, tip: "Falling water spins the turbines, which drive the generators that produce electricity." },
  { id: 50, question: "Which one of the following is not a product mined in connection with petroleum?", options: ["Asphalt", "Coke", "Ethane", "Methane"], correctAnswer: 1, tip: "Coke is produced from coal, not petroleum." },
];

geographyTests[7] = test8;

const test9: Question[] = [
  { id: 1, question: "What is the six figure grid reference of the Chishwingo ruins national monument in the South Western part of the map?", options: ["162 777", "167 772", "772 167", "777 162"], correctAnswer: 0, tip: "Eastings first then northings — the ruins lie at 162 777." },
  { id: 2, question: "Which of the following is found in grid square 1680?", options: ["Ferry", "Hospital", "School", "Tank"], correctAnswer: 2, tip: "The map symbol in square 1680 indicates a school." },
  { id: 3, question: "What is the bearing of the trigonometrical station in grid square 2088 from the spot height in grid square 1585?", options: ["45°", "60°", "235°", "300°"], correctAnswer: 0, tip: "Measured clockwise from north, the trig station lies to the north-east at about 45°." },
  { id: 4, question: "What is the distance along the road in grid square 1780 to the dam in grid square 2084?", options: ["5200 metres", "5400 metres", "6100 metres", "6400 metres"], correctAnswer: 2, tip: "Measuring with a string and applying the 1:50 000 scale gives about 6100 m." },
  { id: 5, question: "What is the direction of the Wayerera school in grid square 1878 from the hospital in grid square 2287?", options: ["North East", "North West", "South East", "South West"], correctAnswer: 3, tip: "Square 1878 lies south-west of square 2287." },
  { id: 6, question: "The settlement pattern in between Easting 20 and 24 and Northings 77 and 79 is ...", options: ["dispersed.", "linear.", "nuclear.", "random."], correctAnswer: 0, tip: "Houses spread out widely in this area form a dispersed pattern." },
  { id: 7, question: "What economic activity has greatly contributed to the settlement in the area shown in the map extract?", options: ["Agriculture", "Mining", "Railway transport", "Road transport"], correctAnswer: 2, tip: "The railway and station around the settlement attracted growth there." },
  { id: 8, question: "The dominant vegetation type of Bindura is ...", options: ["dense bush.", "medium bush.", "open grassland.", "sparse bush."], correctAnswer: 1, tip: "The vegetation symbols across most of the extract indicate medium bush." },
  { id: 9, question: "What is the vertical interval of the map of Bindura?", options: ["15 metres", "20 metres", "25 metres", "30 metres"], correctAnswer: 1, tip: "Contour lines on the Bindura extract are drawn at 20 m intervals." },
  { id: 10, question: "In which direction does the Mazowe River flow?", options: ["North East", "North West", "South East", "South West"], correctAnswer: 0, tip: "Contour heights drop toward the north-east, so the Mazowe flows in that direction." },
  { id: 11, question: "What is the average of the land gradient between the spot height in grid square 1585 and the Trigonometrical station in grid square 2088?", options: ["1 : 10", "1 : 29", "1 : 34", "1 : 44"], correctAnswer: 2, tip: "Gradient = vertical drop ÷ horizontal distance ≈ 1 : 34." },
  { id: 12, question: "What man-made feature is found in grid square 2289?", options: ["Dam", "Dip tank", "Swimming pool", "Water tank"], correctAnswer: 1, tip: "The map symbol in square 2289 marks a dip tank used for treating cattle." },
  { id: 13, question: "What is the approximate straight line distance between Cape Town 33°S and Tropic of Capricorn 23½°S?", options: ["1054.5km", "2608.5km", "3663.0km", "6216.0km"], correctAnswer: 0, tip: "Difference in latitude = 9.5°; 9.5 × 111 km ≈ 1054.5 km." },
  { id: 14, question: "Which among these planets completes its orbit in about three months?", options: ["Earth", "Mars", "Mercury", "Venus"], correctAnswer: 2, tip: "Mercury orbits the Sun in about 88 days (≈ 3 months)." },
  { id: 15, question: "Weathering takes place in each of the following ways except ...", options: ["action of plants and animals.", "alternate wetting and drying.", "dissolving of soluble minerals by rain water.", "removal of top soil by running water."], correctAnswer: 3, tip: "Removal of top soil by running water is erosion, not weathering." },
  { id: 16, question: "The above diagram (rapid swirling currents, turbulent waves, circulating water) shows a river in its ...", options: ["lower course.", "middle course.", "upper course.", "vertical course."], correctAnswer: 2, tip: "Turbulent, swirling currents and rapid flow are typical of the upper course of a river." },
  { id: 17, question: "What type of erosion is taking place at A (the outer bank of a meander)?", options: ["Lateral corrasion", "Lateral corrosion", "Vertical corrasion", "Vertical corrosion"], correctAnswer: 0, tip: "Sideways scouring of the outer bank by sediment-laden water is lateral corrasion." },
  { id: 18, question: "Which one of the following types of weathering does not involve chemical processes?", options: ["Biological", "Exfoliation", "Hydrolysis", "Oxidation"], correctAnswer: 1, tip: "Exfoliation is mechanical (physical) weathering caused by temperature changes." },
  { id: 19, question: "The diagram (cross section showing a knickpoint where an old profile meets a new lower base level) illustrates ...", options: ["Formation of rapids", "River flooding", "River rejuvenation", "River terracing"], correctAnswer: 2, tip: "When a river renews its down-cutting because of a fall in base level, it is said to have been rejuvenated." },
  { id: 20, question: "What features would lead to the formation of such a (dendritic) drainage pattern?", options: ["Alternate clay and sand soils dipping in the same direction.", "Alternate hard and soft rocks dipping in the same direction.", "Flat land with alternate hard and soft rocks.", "Rock with some resistance to erosion."], correctAnswer: 3, tip: "A dendritic pattern develops on uniform rocks of moderate, even resistance to erosion." },
  { id: 21, question: "Which of the following agents of denudation cause mass wasting?", options: ["Gentle slope", "Gravitational force", "Mass of the material", "Rain water"], correctAnswer: 1, tip: "Mass wasting is the movement of weathered material down a slope under gravity." },
  { id: 22, question: "What feature is formed by pebbles in a fast flowing river?", options: ["Inter-locking spurs", "Pot-holes", "Steep gradient", "Waterfalls"], correctAnswer: 1, tip: "Pebbles swirled by eddies grind circular hollows in the river bed called pot-holes." },
  { id: 23, question: "Weather refers to the state of the ...", options: ["atmosphere.", "ionosphere.", "troposphere.", "stratosphere."], correctAnswer: 0, tip: "Weather is the day-to-day state of the atmosphere at a given place." },
  { id: 24, question: "The difference between highest mean monthly temperature and lowest mean monthly temperature is called the ...", options: ["annual temperature range.", "mean annual temperature.", "mean monthly temperature.", "monthly temperature range."], correctAnswer: 0, tip: "That difference over the year is the annual temperature range." },
  { id: 25, question: "The humidity of the air depends on ...", options: ["clouds.", "rain.", "temperature.", "water vapour."], correctAnswer: 3, tip: "Humidity is a measure of the amount of water vapour in the air." },
  { id: 26, question: "The symbol above (a circle divided into four equal quadrants by two intersecting lines) shows ...", options: ["complete cloud cover.", "seven-eighths cover.", "three-quarter cover.", "sky obscured."], correctAnswer: 3, tip: "A circle crossed by two diagonal lines is the standard symbol for sky obscured." },
  { id: 27, question: "Which one of the following places P, Q, R and S experiences westerly winds in winter and offshore winds in summer?", options: ["P", "Q", "R", "S"], correctAnswer: 3, tip: "Mediterranean climates (e.g. the Cape, S) have westerlies in winter and offshore winds in summer." },
  { id: 28, question: "The Tropical Continental Savanna type of climate is best described as having ...", options: ["winter rain and summer drought.", "summer rain and winter drought.", "mud, hot, wet autumn and cool dry spring.", "much rain all year round."], correctAnswer: 1, tip: "Savanna climate has a wet summer and a dry winter." },
  { id: 29, question: "The diagram (high pressure with isobars 1030, 1028, 1026 mb and arrows pointing outward) shows ...", options: ["a cyclone in the Northern hemisphere.", "a cyclone in the Southern hemisphere.", "an anticyclone in the Northern hemisphere.", "an anticyclone in the Southern hemisphere."], correctAnswer: 2, tip: "A high-pressure system with winds blowing out clockwise is a Northern Hemisphere anticyclone." },
  { id: 30, question: "One of the main features of the Mediterranean climate is the ...", options: ["nature of local winds.", "prevailing westerly winds in winter.", "annual temperature range of less than 10°C.", "influence of the ocean currents."], correctAnswer: 1, tip: "Westerly winds bring the characteristic winter rains to Mediterranean regions." },
  { id: 31, question: "Which one of the following climatic regions is associated with open evergreen woodland?", options: ["Equatorial", "Mediterranean", "Tropical Monsoon", "Savanna"], correctAnswer: 1, tip: "Mediterranean regions have open evergreen woodland (cork oak, olive, cypress)." },
  { id: 32, question: "Cacti are typical plants of ...", options: ["hot desert.", "hot wet equatorial.", "Mediterranean.", "tropical continental."], correctAnswer: 0, tip: "Cacti are succulent xerophytes adapted to hot desert conditions." },
  { id: 33, question: "Which one of the following African countries has the highest population?", options: ["Democratic Republic of Congo", "Egypt", "Ethiopia", "South Africa"], correctAnswer: 2, tip: "Ethiopia has the largest population of the four (over 100 million)." },
  { id: 34, question: "The average number of children that would be born to each woman during her reproductive period is known as ...", options: ["birth rate.", "fertility rate.", "life expectancy.", "mortality."], correctAnswer: 1, tip: "Fertility rate measures the average number of children a woman bears during her reproductive years." },
  { id: 35, question: "Which one of the following statements is applicable to the third world countries?", options: ["Experiences least life expectancy.", "Generally records lowest birth-rate.", "Normally maintains a higher standard of living.", "Usually exports large quantities of manufactured goods."], correctAnswer: 0, tip: "Third world countries typically have the lowest life expectancy." },
  { id: 36, question: "The growth of population creates an urgent need for ...", options: ["commercial activities.", "extensive agriculture.", "housing.", "industrialisation."], correctAnswer: 2, tip: "More people first need somewhere to live — housing is the most urgent need." },
  { id: 37, question: "Which one of the following crops would best suit drought conditions of most parts of Africa?", options: ["Maize", "Rice", "Sorghum", "Wheat"], correctAnswer: 2, tip: "Sorghum is highly drought-tolerant and grows well in dry African conditions." },
  { id: 38, question: "In an area of extensive livestock farming, under what conditions are cattle likely to be replaced by sheep?", options: ["When markets become closer.", "When transport becomes better.", "When land becomes less drained.", "When pasture becomes sparser because of less rainfall."], correctAnswer: 3, tip: "Sheep tolerate sparser pasture and drier conditions better than cattle." },
  { id: 39, question: "Which one of the following crops is mainly produced in the shaded area (south-eastern Africa)?", options: ["Maize", "Rice", "Sugarcane", "Wheat"], correctAnswer: 2, tip: "South-eastern Africa (KwaZulu-Natal, Mozambique) is a major sugarcane-growing area." },
  { id: 40, question: "Which among these crops requires heavy annual rainfall of at least 1,270mm, mean temperature of 18°C to 27°C, a warm, dry period for harvesting and loam or clay soil?", options: ["Maize", "Rice", "Tea", "Wheat"], correctAnswer: 1, tip: "These conditions — heavy rain, warm temperatures and clay soils — match rice." },
  { id: 41, question: "Which among these countries is the highest producer of tea?", options: ["Bangladesh", "India", "Indonesia", "Sri-Lanka"], correctAnswer: 1, tip: "India is among the world's largest tea producers, leading these four." },
  { id: 42, question: "Over cropping is when ...", options: ["a high yield of the same crop year after year is produced.", "the same crop is planted on the same land year after year.", "too many crops are grown on the same land year after year.", "too many domestic animals are feeding on the same land year after year."], correctAnswer: 2, tip: "Over-cropping is growing too many crops repeatedly on the same land, exhausting it." },
  { id: 43, question: "In modern industries, the use of coal as a fuel has declined sharply mainly because ...", options: ["it does not yield any industrial by-product.", "it is a very expensive fuel.", "it is not easily available.", "other alternative fuels are more efficient."], correctAnswer: 3, tip: "Cleaner and more efficient fuels (oil, gas, electricity) have largely replaced coal." },
  { id: 44, question: "Oil tankers today are increasing in size because ...", options: ["transportation costs per unit oil is low.", "there is no risk of fire.", "they can carry other cargo.", "they sail the deep seas."], correctAnswer: 0, tip: "Larger tankers spread fixed costs over more cargo, lowering cost per barrel." },
  { id: 45, question: "Despite having a vast potential water power resource, Africa's developed hydro-electric power is about 1% of the world's total. Which one of the following is the reason for this underdevelopment?", options: ["Lack of capital.", "Lack of political will.", "Lack of water resources.", "Rivers dry up during the dry season."], correctAnswer: 0, tip: "African HEP development is held back mainly by shortage of investment capital." },
  { id: 46, question: "Which of the following types of coal burns with great heat and little smoke?", options: ["Anthracite", "Bituminous", "Lignite", "Peat"], correctAnswer: 0, tip: "Anthracite is the highest-rank coal — it burns very hot with little smoke." },
  { id: 47, question: "The hydro-electricity power station industry heavily depends on the following for its successful operation except ...", options: ["large flat land.", "large demand of electricity.", "steep gradient.", "sufficient and constant volume of water."], correctAnswer: 0, tip: "HEP stations actually need a steep slope, not large flat land." },
  { id: 48, question: "Which one of the following minerals is not a source of energy?", options: ["Coal", "Iron", "Petroleum", "Uranium"], correctAnswer: 1, tip: "Iron is a metal used in industry — it is not used to generate energy." },
  { id: 49, question: "The major world producer of coal is ...", options: ["Germany.", "South Africa.", "United Kingdom.", "Sweden."], correctAnswer: 1, tip: "Of the four listed, South Africa is the largest coal producer." },
  { id: 50, question: "When the coal seam is found deep under the sea, the method of mining used is ...", options: ["marine mining.", "open cast mining.", "strip mining.", "shaft mining."], correctAnswer: 3, tip: "Shaft mining sinks vertical shafts to reach deep coal seams, including those under the sea." },
];

